insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary) values
('Мединский курс (Том 2)', '1', 'إِنَّ وَلَعَلَّ (частицы إِنَّ и لَعَلَّ)', '<b>Суть правила.</b> إِنَّ усиливает утверждение, а لَعَلَّ выражает надежду или вероятность. Обе частицы ставят свое имя в винительный падеж, а сказуемое оставляют в именительном. Со слитными местоимениями получаются إِنِّي، إِنَّكَ، إِنَّهُ и لَعَلِّي، لَعَلَّكَ، لَعَلَّهُ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">إِنَّ الطَّالِبَ مُجْتَهِدٌ.</b> — Поистине, студент усердный.</li><li><b dir="rtl" lang="ar">لَعَلَّهُمْ فِي الْفَصْلِ.</b> — Возможно, они в классе.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">إِنَّ الطَّالِبَ مُجْتَهِدٌ.</b> найдите конструкцию «إِنَّ وَلَعَلَّ», определите её роль и только затем сопоставьте с переводом: «Поистине, студент усердный.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'إِنَّ усиливает утверждение, а لَعَلَّ выражает надежду или вероятность. Обе частицы ставят свое имя в винительный падеж, а сказуемое оставляют в именительном. Со слитными местоимениями получаются إِنِّي، إِنَّكَ، إِنَّهُ и لَعَلِّي، لَعَلّ'),
('Мединский курс (Том 2)', '1', 'أَمْ وَهَمْزَةُ التَّعْيِينِ (أَمْ и вопрос с выбором)', '<b>Суть правила.</b> В вопросе с двумя вариантами перед первым ставится أَ, между вариантами — أَمْ. Ответом должен быть выбранный вариант, а не «да» или «нет».<div class="rule-steps"><b>Как применять.</b><ol><li>Поставьте вопросительное слово в начало.</li><li>Сохраните обычное управление глагола или предлога.</li><li>Проверьте, отвечает ли фраза именно на заданный вопрос.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَمِنَ الْهِنْدِ أَنْتَ أَمْ مِنْ بَاكِسْتَانَ؟</b> — Ты из Индии или из Пакистана?</li><li><b dir="rtl" lang="ar">مَاذَا تَقْرَأُ؟ أَقْرَأُ كِتَابًا.</b> — Что ты читаешь? Я читаю книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَمِنَ الْهِنْدِ أَنْتَ أَمْ مِنْ بَاكِسْتَانَ؟</b> найдите конструкцию «أَمْ وَهَمْزَةُ التَّعْيِينِ», определите её роль и только затем сопоставьте с переводом: «Ты из Индии или из Пакистана?».</div><div class="rule-note"><b>Частая ошибка.</b> Не смешивайте مَنْ для разумных лиц и مَا / مَاذَا для предметов, явлений и прочего неразумного.</div>', '2', 'rule', 'В вопросе с двумя вариантами перед первым ставится أَ, между вариантами — أَمْ. Ответом должен быть выбранный вариант, а не «да» или «нет».'),
('Мединский курс (Том 2)', '1', 'ذُو وَذَاتُ (обладающий и обладающая)', '<b>Суть правила.</b> ذُو означает «обладающий» и входит в идафу. Женская форма — ذَاتُ, мужское множественное — ذَوُو, женское — ذَوَاتُ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذَا رَجُلٌ ذُو خُلُقٍ.</b> — Это человек с хорошим нравом.</li><li><b dir="rtl" lang="ar">هَذِهِ طَالِبَةٌ ذَاتُ عِلْمٍ.</b> — Это студентка, обладающая знанием.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هَذَا رَجُلٌ ذُو خُلُقٍ.</b> найдите конструкцию «ذُو وَذَاتُ», определите её роль и только затем сопоставьте с переводом: «Это человек с хорошим нравом.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'ذُو означает «обладающий» и входит в идафу. Женская форма — ذَاتُ, мужское множественное — ذَوُو, женское — ذَوَاتُ.'),
('Мединский курс (Том 2)', '1', 'الِاسْمُ الْمَنْقُوصُ (недостаточное имя)', '<b>Суть правила.</b> Имя на ي, перед которой стоит касра, называется недостаточным. В неопределенной форме именительного и родительного падежей ي опускается и заменяется танвином.<div class="rule-steps"><b>Как применять.</b><ol><li>Поставьте вопросительное слово в начало.</li><li>Сохраните обычное управление глагола или предлога.</li><li>Проверьте, отвечает ли фраза именно на заданный вопрос.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذَا قَاضٍ.</b> — Это судья.</li><li><b dir="rtl" lang="ar">سَلَّمْتُ عَلَى قَاضٍ.</b> — Я поприветствовал судью.</li><li><b dir="rtl" lang="ar">مَاذَا تَقْرَأُ؟ أَقْرَأُ كِتَابًا.</b> — Что ты читаешь? Я читаю книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هَذَا قَاضٍ.</b> найдите конструкцию «الِاسْمُ الْمَنْقُوصُ», определите её роль и только затем сопоставьте с переводом: «Это судья.».</div><div class="rule-note"><b>Частая ошибка.</b> Не смешивайте مَنْ для разумных лиц и مَا / مَاذَا для предметов, явлений и прочего неразумного.</div>', '4', 'rule', 'Имя на ي, перед которой стоит касра, называется недостаточным. В неопределенной форме именительного и родительного падежей ي опускается и заменяется танвином.'),
('Мединский курс (Том 2)', '1', 'مِائَةٌ وَأَلْفٌ (числа сто и тысяча)', '<b>Суть правила.</b> После مِائَة и أَلْف считаемое имя стоит в единственном числе и родительном падеже. Форма числа не зависит от рода предмета.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مِائَةُ كِتَابٍ.</b> — Сто книг.</li><li><b dir="rtl" lang="ar">أَلْفُ سَيَّارَةٍ.</b> — Тысяча автомобилей.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">مِائَةُ كِتَابٍ.</b> найдите конструкцию «مِائَةٌ وَأَلْفٌ», определите её роль и только затем сопоставьте с переводом: «Сто книг.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '5', 'rule', 'После مِائَة и أَلْف считаемое имя стоит в единственном числе и родительном падеже. Форма числа не зависит от рода предмета.'),
('Мединский курс (Том 2)', '2', 'لَيْسَ وَضَمَائِرُهَا (لَيْسَ и ее формы)', '<b>Суть правила.</b> لَيْسَ отрицает состояние в настоящем. Ее имя именительное, сказуемое винительное. Запомните: لَسْتُ، لَسْنَا، لَسْتَ، لَيْسَ، لَيْسَتْ، لَيْسُوا، لَسْنَ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَسْتُ مُتْعَبًا.</b> — Я не устал.</li><li><b dir="rtl" lang="ar">لَسْنَ غَائِبَاتٍ.</b> — Они, женщины, не отсутствуют.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَسْتُ مُتْعَبًا.</b> найдите конструкцию «لَيْسَ وَضَمَائِرُهَا», определите её роль и только затем сопоставьте с переводом: «Я не устал.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'لَيْسَ отрицает состояние в настоящем. Ее имя именительное, сказуемое винительное. Запомните: لَسْتُ، لَسْنَا، لَسْتَ، لَيْسَ، لَيْسَتْ، لَيْسُوا، لَسْنَ.'),
('Мединский курс (Том 2)', '2', 'الْبَاءُ الزَّائِدَةُ فِي خَبَرِ لَيْسَ (усилительная بِ в сказуемом لَيْسَ)', '<b>Суть правила.</b> К сказуемому может присоединяться بِ. По форме слово становится родительным, но синтаксически остается сказуемым в винительном положении.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَيْسَ الطَّالِبُ بِغَائِبٍ.</b> — Студент вовсе не отсутствует.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَيْسَ الطَّالِبُ بِغَائِبٍ.</b> найдите конструкцию «الْبَاءُ الزَّائِدَةُ فِي خَبَرِ لَيْسَ», определите её роль и только затем сопоставьте с переводом: «Студент вовсе не отсутствует.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'К сказуемому может присоединяться بِ. По форме слово становится родительным, но синтаксически остается сказуемым в винительном положении.'),
('Мединский курс (Том 2)', '2', 'تَقْدِيمُ خَبَرِ إِنَّ (сказуемое إِنَّ перед ее именем)', '<b>Суть правила.</b> Сказуемое-обстоятельство или сочетание с предлогом может стоять перед именем إِنَّ. Имя все равно остается винительным.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">إِنَّ فِي الْفَصْلِ طَالِبًا.</b> — Поистине, в классе есть студент.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">إِنَّ فِي الْفَصْلِ طَالِبًا.</b> найдите конструкцию «تَقْدِيمُ خَبَرِ إِنَّ», определите её роль и только затем сопоставьте с переводом: «Поистине, в классе есть студент.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'Сказуемое-обстоятельство или сочетание с предлогом может стоять перед именем إِنَّ. Имя все равно остается винительным.'),
('Мединский курс (Том 2)', '3', 'اسْمُ التَّفْضِيلِ (сравнительная и превосходная степень)', '<b>Суть правила.</b> Модель أَفْعَلُ передает «более» или «самый». С مِنْ это сравнение, а в идафе или с ال — превосходная степень.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">خَالِدٌ أَطْوَلُ مِنْ حَامِدٍ.</b> — Халид выше Хамида.</li><li><b dir="rtl" lang="ar">هُوَ أَحْسَنُ الطُّلَّابِ.</b> — Он лучший из студентов.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">خَالِدٌ أَطْوَلُ مِنْ حَامِدٍ.</b> найдите конструкцию «اسْمُ التَّفْضِيلِ», определите её роль и только затем сопоставьте с переводом: «Халид выше Хамида.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'Модель أَفْعَلُ передает «более» или «самый». С مِنْ это сравнение, а в идафе или с ال — превосходная степень.'),
('Мединский курс (Том 2)', '3', 'لَكِنَّ وَكَأَنَّ (частицы «но» и «как будто»)', '<b>Суть правила.</b> لَكِنَّ выражает противопоставление, كَأَنَّ — уподобление. Они действуют как إِنَّ: имя винительное, сказуемое именительное.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">الْبَيْتُ صَغِيرٌ لَكِنَّهُ جَمِيلٌ.</b> — Дом маленький, но красивый.</li><li><b dir="rtl" lang="ar">كَأَنَّ الْقَمَرَ مِصْبَاحٌ.</b> — Луна словно светильник.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">الْبَيْتُ صَغِيرٌ لَكِنَّهُ جَمِيلٌ.</b> найдите конструкцию «لَكِنَّ وَكَأَنَّ», определите её роль и только затем сопоставьте с переводом: «Дом маленький, но красивый.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'لَكِنَّ выражает противопоставление, كَأَنَّ — уподобление. Они действуют как إِنَّ: имя винительное, сказуемое именительное.'),
('Мединский курс (Том 2)', '3', 'الْأَعْدَادُ ١١–٩٠ (числа 11–90)', '<b>Суть правила.</b> В 11 и 12 обе части согласуются с родом. В 13–19 первая часть противоположна роду, а عَشَر/عَشْرَة согласуется. Десятки склоняются через ـُونَ/ـِينَ; считаемое слово единственное винительное.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ثَلَاثَةَ عَشَرَ طَالِبًا.</b> — Тринадцать студентов.</li><li><b dir="rtl" lang="ar">رَأَيْتُ عِشْرِينَ طَالِبًا.</b> — Я увидел двадцать студентов.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">ثَلَاثَةَ عَشَرَ طَالِبًا.</b> найдите конструкцию «الْأَعْدَادُ ١١–٩٠», определите её роль и только затем сопоставьте с переводом: «Тринадцать студентов.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '3', 'rule', 'В 11 и 12 обе части согласуются с родом. В 13–19 первая часть противоположна роду, а عَشَر/عَشْرَة согласуется. Десятки склоняются через ـُونَ/ـِينَ; считаемое слово единственное винительное.'),
('Мединский курс (Том 2)', '3', 'الْعَدَدُ التَّرْتِيبِيُّ (порядковые числительные)', '<b>Суть правила.</b> Порядковое числительное является прилагательным и согласуется с существительным в роде, определенности и падеже.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">الدَّرْسُ الثَّالِثُ.</b> — Третий урок.</li><li><b dir="rtl" lang="ar">الصَّفْحَةُ الْخَامِسَةُ.</b> — Пятая страница.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">الدَّرْسُ الثَّالِثُ.</b> найдите конструкцию «الْعَدَدُ التَّرْتِيبِيُّ», определите её роль и только затем сопоставьте с переводом: «Третий урок.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '4', 'rule', 'Порядковое числительное является прилагательным и согласуется с существительным в роде, определенности и падеже.'),
('Мединский курс (Том 2)', '3', 'الِاسْتِفْهَامُ الْمَنْفِيُّ وَأَيُّهُمَا (отрицательный вопрос и «который из двух?»)', '<b>Суть правила.</b> بَلَى отменяет отрицание и означает «да, наоборот», а نَعَمْ подтверждает отрицание. أَيُّهُمَا требует выбрать одного из двух.<div class="rule-steps"><b>Как применять.</b><ol><li>Поставьте вопросительное слово в начало.</li><li>Сохраните обычное управление глагола или предлога.</li><li>Проверьте, отвечает ли фраза именно на заданный вопрос.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَلَيْسَ هَذَا كِتَابَكَ؟ بَلَى.</b> — Разве это не твоя книга? Да, моя.</li><li><b dir="rtl" lang="ar">أَيُّهُمَا أَكْبَرُ؟</b> — Который из них двоих старше?</li><li><b dir="rtl" lang="ar">مَاذَا تَقْرَأُ؟ أَقْرَأُ كِتَابًا.</b> — Что ты читаешь? Я читаю книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَلَيْسَ هَذَا كِتَابَكَ؟ بَلَى.</b> найдите конструкцию «الِاسْتِفْهَامُ الْمَنْفِيُّ وَأَيُّهُمَا», определите её роль и только затем сопоставьте с переводом: «Разве это не твоя книга? Да, моя.».</div><div class="rule-note"><b>Частая ошибка.</b> Не смешивайте مَنْ для разумных лиц и مَا / مَاذَا для предметов, явлений и прочего неразумного.</div>', '5', 'rule', 'بَلَى отменяет отрицание и означает «да, наоборот», а نَعَمْ подтверждает отрицание. أَيُّهُمَا требует выбрать одного из двух.'),
('Мединский курс (Том 2)', '4', 'إِسْنَادُ الْفِعْلِ الْمَاضِي (спряжение прошедшего времени)', '<b>Суть правила.</b> Основа получает окончания лица и числа: ـْتُ، ـْنَا، ـْتَ، ـْتِ، ـَ، ـَتْ، ـُوا، ـْنَ. Окончание сразу указывает исполнителя.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ذَهَبْتُ.</b> — Я пошел.</li><li><b dir="rtl" lang="ar">ذَهَبُوا.</b> — Они пошли.</li><li><b dir="rtl" lang="ar">ذَهَبْنَ.</b> — Они, женщины, пошли.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">ذَهَبْتُ.</b> найдите конструкцию «إِسْنَادُ الْفِعْلِ الْمَاضِي», определите её роль и только затем сопоставьте с переводом: «Я пошел.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Основа получает окончания лица и числа: ـْتُ، ـْنَا، ـْتَ، ـْتِ، ـَ، ـَتْ، ـُوا، ـْنَ. Окончание сразу указывает исполнителя.'),
('Мединский курс (Том 2)', '4', 'مَا النَّافِيَةُ (отрицание прошедшего через مَا)', '<b>Суть правила.</b> مَا ставится перед прошедшим глаголом и не меняет его форму.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا ذَهَبَ حَامِدٌ.</b> — Хамид не пошел.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">مَا ذَهَبَ حَامِدٌ.</b> найдите конструкцию «مَا النَّافِيَةُ», определите её роль и только затем сопоставьте с переводом: «Хамид не пошел.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '2', 'rule', 'مَا ставится перед прошедшим глаголом и не меняет его форму.'),
('Мединский курс (Том 2)', '4', 'لِأَنَّ (союз «потому что»)', '<b>Суть правила.</b> لِأَنَّ вводит причину и действует как إِنَّ. Присоединенное местоимение или явное имя является ее именем.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">غِبْتُ لِأَنَّنِي مَرِيضٌ.</b> — Я отсутствовал, потому что болен.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">غِبْتُ لِأَنَّنِي مَرِيضٌ.</b> найдите конструкцию «لِأَنَّ», определите её роль и только затем сопоставьте с переводом: «Я отсутствовал, потому что болен.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'لِأَنَّ вводит причину и действует как إِنَّ. Присоединенное местоимение или явное имя является ее именем.'),
('Мединский курс (Том 2)', '5', 'الْفَاعِلُ وَالْمَفْعُولُ بِهِ (исполнитель и прямое дополнение)', '<b>Суть правила.</b> Исполнитель действия стоит в именительном падеже, а предмет действия — в винительном. При порядке «глагол + явный исполнитель» глагол обычно остается единственным.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ.</b> — Студент написал урок.</li><li><b dir="rtl" lang="ar">كَتَبَ الطُّلَّابُ الدَّرْسَ.</b> — Студенты написали урок.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ.</b> найдите конструкцию «الْفَاعِلُ وَالْمَفْعُولُ بِهِ», определите её роль и только затем сопоставьте с переводом: «Студент написал урок.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'Исполнитель действия стоит в именительном падеже, а предмет действия — в винительном. При порядке «глагол + явный исполнитель» глагол обычно остается единственным.'),
('Мединский курс (Том 2)', '5', 'ضَمَائِرُ الرَّفْعِ الْمُتَّصِلَةُ (слитные местоимения-исполнители)', '<b>Суть правила.</b> تاء الفاعل, نا, ألف الاثنين, واو الجماعة и نون النسوة присоединяются к глаголу и сами обозначают исполнителя.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите, кого или что заменяет местоимение.</li><li>Проверьте род и число.</li><li>Уточните позицию: отдельная форма или слитный суффикс.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبْتُمْ.</b> — Вы написали.</li><li><b dir="rtl" lang="ar">كَتَبْنَ.</b> — Они, женщины, написали.</li><li><b dir="rtl" lang="ar">رَأَيْتُهَا وَسَأَلْتُهَا عَنِ الدَّرْسِ.</b> — Я увидел её и спросил её об уроке.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كَتَبْتُمْ.</b> найдите конструкцию «ضَمَائِرُ الرَّفْعِ الْمُتَّصِلَةُ», определите её роль и только затем сопоставьте с переводом: «Вы написали.».</div><div class="rule-note"><b>Частая ошибка.</b> Слитное местоимение меняет функцию по контексту: оно может выражать принадлежность или дополнение.</div>', '2', 'rule', 'تاء الفاعل, نا, ألف الاثنين, واو الجماعة и نون النسوة присоединяются к глаголу и сами обозначают исполнителя.'),
('Мединский курс (Том 2)', '5', 'ضَمَائِرُ النَّصْبِ الْمُتَّصِلَةُ (слитные местоимения-дополнения)', '<b>Суть правила.</b> ـنِي، ـنَا، ـكَ، ـهُ، ـهَا، ـهُمْ и другие формы присоединяются к глаголу как прямое дополнение.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите, кого или что заменяет местоимение.</li><li>Проверьте род и число.</li><li>Уточните позицию: отдельная форма или слитный суффикс.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَأَيْتُهُ.</b> — Я увидел его.</li><li><b dir="rtl" lang="ar">سَأَلَنَا الْمُدَرِّسُ.</b> — Учитель спросил нас.</li><li><b dir="rtl" lang="ar">رَأَيْتُهَا وَسَأَلْتُهَا عَنِ الدَّرْسِ.</b> — Я увидел её и спросил её об уроке.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">رَأَيْتُهُ.</b> найдите конструкцию «ضَمَائِرُ النَّصْبِ الْمُتَّصِلَةُ», определите её роль и только затем сопоставьте с переводом: «Я увидел его.».</div><div class="rule-note"><b>Частая ошибка.</b> Слитное местоимение меняет функцию по контексту: оно может выражать принадлежность или дополнение.</div>', '3', 'rule', 'ـنِي، ـنَا، ـكَ، ـهُ، ـهَا، ـهُمْ и другие формы присоединяются к глаголу как прямое дополнение.'),
('Мединский курс (Том 2)', '5', 'تَاءُ التَّأْنِيثِ السَّاكِنَةُ (показатель женского рода в прошедшем)', '<b>Суть правила.</b> С явным исполнителем женского рода прошедший глагол получает ـتْ. Эта ت только указывает род и не является местоимением.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ذَهَبَتْ آمِنَةُ.</b> — Амина ушла.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">ذَهَبَتْ آمِنَةُ.</b> найдите конструкцию «تَاءُ التَّأْنِيثِ السَّاكِنَةُ», определите её роль и только затем сопоставьте с переводом: «Амина ушла.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '4', 'rule', 'С явным исполнителем женского рода прошедший глагол получает ـتْ. Эта ت только указывает род и не является местоимением.'),
('Мединский курс (Том 2)', '6', 'تَأْنِيثُ الْفِعْلِ مَعَ الْفَاعِلِ (согласование с женским исполнителем)', '<b>Суть правила.</b> Если после глагола стоит женщина или женское единственное имя, прошедший глагол получает تاء التأنيث.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">حَضَرَتِ الطَّالِبَةُ.</b> — Студентка пришла.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">حَضَرَتِ الطَّالِبَةُ.</b> найдите конструкцию «تَأْنِيثُ الْفِعْلِ مَعَ الْفَاعِلِ», определите её роль и только затем сопоставьте с переводом: «Студентка пришла.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Если после глагола стоит женщина или женское единственное имя, прошедший глагол получает تاء التأنيث.'),
('Мединский курс (Том 2)', '6', 'ضَمَائِرُ الْغَائِبِ مَفْعُولًا بِهِ (местоимения третьего лица как дополнение)', '<b>Суть правила.</b> ـهُ، ـهَا، ـهُمَا، ـهُمْ، ـهُنَّ присоединяются непосредственно к глаголу.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите, кого или что заменяет местоимение.</li><li>Проверьте род и число.</li><li>Уточните позицию: отдельная форма или слитный суффикс.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَأَيْتُهُمْ.</b> — Я увидел их.</li><li><b dir="rtl" lang="ar">سَأَلْتُهَا.</b> — Я спросил ее.</li><li><b dir="rtl" lang="ar">رَأَيْتُهَا وَسَأَلْتُهَا عَنِ الدَّرْسِ.</b> — Я увидел её и спросил её об уроке.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">رَأَيْتُهُمْ.</b> найдите конструкцию «ضَمَائِرُ الْغَائِبِ مَفْعُولًا بِهِ», определите её роль и только затем сопоставьте с переводом: «Я увидел их.».</div><div class="rule-note"><b>Частая ошибка.</b> Слитное местоимение меняет функцию по контексту: оно может выражать принадлежность или дополнение.</div>', '2', 'rule', 'ـهُ، ـهَا، ـهُمَا، ـهُمْ، ـهُنَّ присоединяются непосредственно к глаголу.'),
('Мединский курс (Том 2)', '6', 'أَنَّ (союз «что»)', '<b>Суть правила.</b> أَنَّ вводит придаточное и действует как إِنَّ: имя получает винительный падеж, сказуемое — именительный.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَظُنُّ أَنَّ الْجَوَّ جَمِيلٌ.</b> — Я думаю, что погода хорошая.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَظُنُّ أَنَّ الْجَوَّ جَمِيلٌ.</b> найдите конструкцию «أَنَّ», определите её роль и только затем сопоставьте с переводом: «Я думаю, что погода хорошая.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'أَنَّ вводит придаточное и действует как إِنَّ: имя получает винительный падеж, сказуемое — именительный.'),
('Мединский курс (Том 2)', '6', 'مُؤَنَّثُ فَعْلَانَ وَجَمْعُهُ (формы модели فَعْلَان)', '<b>Суть правила.</b> Состояния на فَعْلَانُ часто имеют женскую форму فَعْلَى и особое ломаное множественное.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ عَطْشَانُ وَهِيَ عَطْشَى.</b> — Он и она испытывают жажду.</li><li><b dir="rtl" lang="ar">هُمْ عِطَاشٌ.</b> — Они испытывают жажду.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُوَ عَطْشَانُ وَهِيَ عَطْشَى.</b> найдите конструкцию «مُؤَنَّثُ فَعْلَانَ وَجَمْعُهُ», определите её роль и только затем сопоставьте с переводом: «Он и она испытывают жажду.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '4', 'rule', 'Состояния на فَعْلَانُ часто имеют женскую форму فَعْلَى и особое ломаное множественное.'),
('Мединский курс (Том 2)', '6', 'أَنْوَاعُ الْإِعْرَابِ فِي الْأَسْمَاءِ (три падежных состояния имен)', '<b>Суть правила.</b> Имя бывает مرفوعًا, منصوبًا или مجرورًا. Основные признаки единственного имени: дамма, фатха и касра.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите синтаксическую роль слова.</li><li>Выберите требуемый падеж.</li><li>Проверьте окончание с учётом числа и типа имени.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ طَالِبٌ، رَأَيْتُ طَالِبًا، مَرَرْتُ بِطَالِبٍ.</b> — Пришел студент; я увидел студента; я прошел мимо студента.</li><li><b dir="rtl" lang="ar">جَاءَ الطَّالِبُ وَرَأَيْتُ الطَّالِبَ وَسَلَّمْتُ عَلَى الطَّالِبِ.</b> — Ученик пришёл; я увидел ученика и поприветствовал ученика.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جَاءَ طَالِبٌ، رَأَيْتُ طَالِبًا، مَرَرْتُ بِطَالِبٍ.</b> найдите конструкцию «أَنْوَاعُ الْإِعْرَابِ فِي الْأَسْمَاءِ», определите её роль и только затем сопоставьте с переводом: «Пришел студент; я увидел студента; я прошел мимо студента.».</div><div class="rule-note"><b>Частая ошибка.</b> Окончание зависит не только от смысла, но и от позиции слова в предложении.</div>', '5', 'rule', 'Имя бывает مرفوعًا, منصوبًا или مجرورًا. Основные признаки единственного имени: дамма, фатха и касра.'),
('Мединский курс (Том 2)', '6', 'لِمَ وَلِمَهْ وَهَاتِ («почему?» и «дай/принеси»)', '<b>Суть правила.</b> لِمَ образовано из لِ + مَا с удалением алифа; при паузе возможно لِمَهْ. هَاتِ — неизменяемое слово побуждения.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لِمَ غِبْتَ؟</b> — Почему ты отсутствовал?</li><li><b dir="rtl" lang="ar">هَاتِ الْكِتَابَ.</b> — Дай книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لِمَ غِبْتَ؟</b> найдите конструкцию «لِمَ وَلِمَهْ وَهَاتِ», определите её роль и только затем сопоставьте с переводом: «Почему ты отсутствовал?».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '6', 'rule', 'لِمَ образовано из لِ + مَا с удалением алифа; при паузе возможно لِمَهْ. هَاتِ — неизменяемое слово побуждения.'),
('Мединский курс (Том 2)', '7', 'تَأْنِيثُ الْفَاعِلِ الْمُفْرَدِ وَالْجَمْعِ (женский исполнитель в единственном и множественном)', '<b>Суть правила.</b> С реальным женским единственным исполнителем согласование обязательно. Неодушевленное ломаное множественное обычно согласуется как женское единственное.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">حَضَرَتْ فَاطِمَةُ.</b> — Фатима пришла.</li><li><b dir="rtl" lang="ar">سَقَطَتِ الْكُتُبُ.</b> — Книги упали.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">حَضَرَتْ فَاطِمَةُ.</b> найдите конструкцию «تَأْنِيثُ الْفَاعِلِ الْمُفْرَدِ وَالْجَمْعِ», определите её роль и только затем сопоставьте с переводом: «Фатима пришла.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'С реальным женским единственным исполнителем согласование обязательно. Неодушевленное ломаное множественное обычно согласуется как женское единственное.'),
('Мединский курс (Том 2)', '7', 'الْتِقَاءُ السَّاكِنَيْنِ (встреча двух сукунов)', '<b>Суть правила.</b> Два сукуна подряд не произносятся. Первый звук получает вспомогательную гласную или изменяется по установленному правилу.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَالَتِ الطَّالِبَةُ.</b> — Студентка сказала.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">قَالَتِ الطَّالِبَةُ.</b> найдите конструкцию «الْتِقَاءُ السَّاكِنَيْنِ», определите её роль и только затем сопоставьте с переводом: «Студентка сказала.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'Два сукуна подряд не произносятся. Первый звук получает вспомогательную гласную или изменяется по установленному правилу.'),
('Мединский курс (Том 2)', '7', 'كَانَ وَخَبَرُهَا شِبْهُ جُمْلَةٍ (كَانَ со сказуемым-обстоятельством)', '<b>Суть правила.</b> كَانَ переносит состояние в прошлое. Ее имя именительное, сказуемое винительное по позиции; сочетание с предлогом может стоять первым.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَانَ فِي الْفَصْلِ طُلَّابٌ.</b> — В классе были студенты.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كَانَ فِي الْفَصْلِ طُلَّابٌ.</b> найдите конструкцию «كَانَ وَخَبَرُهَا شِبْهُ جُمْلَةٍ», определите её роль и только затем сопоставьте с переводом: «В классе были студенты.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'كَانَ переносит состояние в прошлое. Ее имя именительное, сказуемое винительное по позиции; сочетание с предлогом может стоять первым.'),
('Мединский курс (Том 2)', '7', 'ذُو وَذَاتُ نَعْتًا (ذُو и ذَاتُ как определение)', '<b>Суть правила.</b> Как прилагательное ذُو/ذَاتُ согласуется с определяемым именем в роде, числе, определенности и падеже.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите определяемое существительное.</li><li>Согласуйте прилагательное в роде, числе и определённости.</li><li>Проверьте падежные окончания обоих слов.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ الرَّجُلُ ذُو اللِّحْيَةِ.</b> — Пришел мужчина с бородой.</li><li><b dir="rtl" lang="ar">هَذِهِ سَيَّارَةٌ جَدِيدَةٌ، وَذَلِكَ بَيْتٌ كَبِيرٌ.</b> — Это новая машина, а то большой дом.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جَاءَ الرَّجُلُ ذُو اللِّحْيَةِ.</b> найдите конструкцию «ذُو وَذَاتُ نَعْتًا», определите её роль и только затем сопоставьте с переводом: «Пришел мужчина с бородой.».</div><div class="rule-note"><b>Частая ошибка.</b> Прилагательное не получает артикль само по себе, если определяемое существительное остаётся неопределённым.</div>', '4', 'rule', 'Как прилагательное ذُو/ذَاتُ согласуется с определяемым именем в роде, числе, определенности и падеже.'),
('Мединский курс (Том 2)', '8', 'جَدْوَلُ الْفِعْلِ الْمَاضِي (полная таблица прошедшего времени)', '<b>Суть правила.</b> Спряжение строится от одной основы и набора окончаний. Особо различайте هُمْ ذَهَبُوا и هُنَّ ذَهَبْنَ, أَنْتُمْ ذَهَبْتُمْ и أَنْتُنَّ ذَهَبْتُنَّ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُمَا ذَهَبَا وَهُمَا ذَهَبَتَا.</b> — Они двое ушли: мужская и женская формы.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُمَا ذَهَبَا وَهُمَا ذَهَبَتَا.</b> найдите конструкцию «جَدْوَلُ الْفِعْلِ الْمَاضِي», определите её роль и только затем сопоставьте с переводом: «Они двое ушли: мужская и женская формы.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Спряжение строится от одной основы и набора окончаний. Особо различайте هُمْ ذَهَبُوا и هُنَّ ذَهَبْنَ, أَنْتُمْ ذَهَبْتُمْ и أَنْتُنَّ ذَهَبْتُنَّ.'),
('Мединский курс (Том 2)', '8', 'عَلَامَاتُ التَّصْرِيفِ وَالضَّمَائِرُ (показатели формы и местоимения)', '<b>Суть правила.</b> Не каждое окончание является отдельным местоимением: تاء التأنيث лишь указывает женский род, а تاء الفاعل сама обозначает исполнителя.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبَتْ فَاطِمَةُ؛ كَتَبْتُ.</b> — Фатима написала; я написал.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كَتَبَتْ فَاطِمَةُ؛ كَتَبْتُ.</b> найдите конструкцию «عَلَامَاتُ التَّصْرِيفِ وَالضَّمَائِرُ», определите её роль и только затем сопоставьте с переводом: «Фатима написала; я написал.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '2', 'rule', 'Не каждое окончание является отдельным местоимением: تاء التأنيث лишь указывает женский род, а تاء الفاعل сама обозначает исполнителя.'),
('Мединский курс (Том 2)', '8', 'الضَّمِيرُ الْمُسْتَتِرُ وَالْبَارِزُ (скрытое и выраженное местоимение)', '<b>Суть правила.</b> Исполнитель может быть скрыт внутри формы глагола или явно выражен окончанием/отдельным словом.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите, кого или что заменяет местоимение.</li><li>Проверьте род и число.</li><li>Уточните позицию: отдельная форма или слитный суффикс.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ذَهَبَ: الْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.</b> — В «ушел» скрытый исполнитель «он».</li><li><b dir="rtl" lang="ar">رَأَيْتُهَا وَسَأَلْتُهَا عَنِ الدَّرْسِ.</b> — Я увидел её и спросил её об уроке.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">ذَهَبَ: الْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.</b> найдите конструкцию «الضَّمِيرُ الْمُسْتَتِرُ وَالْبَارِزُ», определите её роль и только затем сопоставьте с переводом: «В «ушел» скрытый исполнитель «он».».</div><div class="rule-note"><b>Частая ошибка.</b> Слитное местоимение меняет функцию по контексту: оно может выражать принадлежность или дополнение.</div>', '3', 'rule', 'Исполнитель может быть скрыт внутри формы глагола или явно выражен окончанием/отдельным словом.'),
('Мединский курс (Том 2)', '8', 'الضَّمِيرُ الْمُتَّصِلُ وَالْمُنْفَصِلُ (слитное и раздельное местоимение)', '<b>Суть правила.</b> Раздельное местоимение пишется самостоятельно, слитное — только вместе с глаголом, именем или предлогом.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите, кого или что заменяет местоимение.</li><li>Проверьте род и число.</li><li>Уточните позицию: отдельная форма или слитный суффикс.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ طَالِبٌ؛ كِتَابُهُ جَدِيدٌ.</b> — Он студент; его книга новая.</li><li><b dir="rtl" lang="ar">رَأَيْتُهَا وَسَأَلْتُهَا عَنِ الدَّرْسِ.</b> — Я увидел её и спросил её об уроке.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُوَ طَالِبٌ؛ كِتَابُهُ جَدِيدٌ.</b> найдите конструкцию «الضَّمِيرُ الْمُتَّصِلُ وَالْمُنْفَصِلُ», определите её роль и только затем сопоставьте с переводом: «Он студент; его книга новая.».</div><div class="rule-note"><b>Частая ошибка.</b> Слитное местоимение меняет функцию по контексту: оно может выражать принадлежность или дополнение.</div>', '4', 'rule', 'Раздельное местоимение пишется самостоятельно, слитное — только вместе с глаголом, именем или предлогом.'),
('Мединский курс (Том 2)', '9', 'فِعْلُ التَّعَجُّبِ (форма восклицания مَا أَفْعَلَهُ)', '<b>Суть правила.</b> Модель مَا أَفْعَلَ выражает сильное впечатление. Предмет впечатления ставится как дополнение.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا أَجْمَلَ السَّمَاءَ!</b> — Как прекрасно небо!</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">مَا أَجْمَلَ السَّمَاءَ!</b> найдите конструкцию «فِعْلُ التَّعَجُّبِ», определите её роль и только затем сопоставьте с переводом: «Как прекрасно небо!».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Модель مَا أَفْعَلَ выражает сильное впечатление. Предмет впечатления ставится как дополнение.'),
('Мединский курс (Том 2)', '9', 'الْمُنَادَى الْمُفْرَدُ وَالْمُضَافُ (обращение: одиночное и в идафе)', '<b>Суть правила.</b> Определенное одиночное обращение строится на дамме, а обращение в идафе стоит в винительном.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите два связанных имени.</li><li>Уберите артикль и танвин у первого члена.</li><li>Поставьте второй член в родительный падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَا مُحَمَّدُ!</b> — О Мухаммад!</li><li><b dir="rtl" lang="ar">يَا عَبْدَ اللهِ!</b> — О раб Аллаха!</li><li><b dir="rtl" lang="ar">بَابُ الْمَدْرَسَةِ مَفْتُوحٌ.</b> — Дверь школы открыта.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">يَا مُحَمَّدُ!</b> найдите конструкцию «الْمُنَادَى الْمُفْرَدُ وَالْمُضَافُ», определите её роль и только затем сопоставьте с переводом: «О Мухаммад!».</div><div class="rule-note"><b>Частая ошибка.</b> Первый член идафы не принимает ال и танвин одновременно с конструкцией принадлежности.</div>', '2', 'rule', 'Определенное одиночное обращение строится на дамме, а обращение в идафе стоит в винительном.'),
('Мединский курс (Том 2)', '9', 'جَمْعُ الْمُؤَنَّثِ السَّالِمُ (правильное женское множественное)', '<b>Суть правила.</b> В именительном окончание ـَاتُ, в винительном и родительном — ـَاتِ. В винительном используется касра.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">حَضَرَتِ الطَّالِبَاتُ.</b> — Студентки пришли.</li><li><b dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَاتِ.</b> — Я увидел студенток.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">حَضَرَتِ الطَّالِبَاتُ.</b> найдите конструкцию «جَمْعُ الْمُؤَنَّثِ السَّالِمُ», определите её роль и только затем сопоставьте с переводом: «Студентки пришли.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'В именительном окончание ـَاتُ, в винительном и родительном — ـَاتِ. В винительном используется касра.'),
('Мединский курс (Том 2)', '9', 'هَمْزَةُ الِاسْتِفْهَامِ مَعَ ال (вопросительная أَ перед артиклем)', '<b>Суть правила.</b> При соединении أَ с ال две хамзы могут перейти в долгий آ для ясного произношения.<div class="rule-steps"><b>Как применять.</b><ol><li>Поставьте вопросительное слово в начало.</li><li>Сохраните обычное управление глагола или предлога.</li><li>Проверьте, отвечает ли фраза именно на заданный вопрос.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">آلطَّالِبُ جَدِيدٌ؟</b> — Этот студент новый?</li><li><b dir="rtl" lang="ar">مَاذَا تَقْرَأُ؟ أَقْرَأُ كِتَابًا.</b> — Что ты читаешь? Я читаю книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">آلطَّالِبُ جَدِيدٌ؟</b> найдите конструкцию «هَمْزَةُ الِاسْتِفْهَامِ مَعَ ال», определите её роль и только затем сопоставьте с переводом: «Этот студент новый?».</div><div class="rule-note"><b>Частая ошибка.</b> Не смешивайте مَنْ для разумных лиц и مَا / مَاذَا для предметов, явлений и прочего неразумного.</div>', '4', 'rule', 'При соединении أَ с ال две хамзы могут перейти в долгий آ для ясного произношения.'),
('Мединский курс (Том 2)', '9', 'ضَمَائِرُ النَّصْبِ وَنُونُ الْوِقَايَةِ (объектные местоимения и защитная ن)', '<b>Суть правила.</b> Перед ي говорящего у глагола появляется نون الوقاية: أَكْرَمَنِي. Она защищает основу от касры.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите, кого или что заменяет местоимение.</li><li>Проверьте род и число.</li><li>Уточните позицию: отдельная форма или слитный суффикс.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">سَأَلَنِي الْمُدَرِّسُ.</b> — Учитель спросил меня.</li><li><b dir="rtl" lang="ar">رَأَيْتُهَا وَسَأَلْتُهَا عَنِ الدَّرْسِ.</b> — Я увидел её и спросил её об уроке.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">سَأَلَنِي الْمُدَرِّسُ.</b> найдите конструкцию «ضَمَائِرُ النَّصْبِ وَنُونُ الْوِقَايَةِ», определите её роль и только затем сопоставьте с переводом: «Учитель спросил меня.».</div><div class="rule-note"><b>Частая ошибка.</b> Слитное местоимение меняет функцию по контексту: оно может выражать принадлежность или дополнение.</div>', '5', 'rule', 'Перед ي говорящего у глагола появляется نون الوقاية: أَكْرَمَنِي. Она защищает основу от касры.'),
('Мединский курс (Том 2)', '9', 'حَذْفُ أَلِفِ مَا الِاسْتِفْهَامِيَّةِ (удаление алифа в вопросительном مَا)', '<b>Суть правила.</b> После предлога алиф вопросительного مَا удаляется: بِمَ، لِمَ، مِمَّ، عَمَّ.<div class="rule-steps"><b>Как применять.</b><ol><li>Поставьте вопросительное слово в начало.</li><li>Сохраните обычное управление глагола или предлога.</li><li>Проверьте, отвечает ли фраза именно на заданный вопрос.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">بِمَ كَتَبْتَ؟</b> — Чем ты написал?</li><li><b dir="rtl" lang="ar">عَمَّ تَسْأَلُ؟</b> — О чем ты спрашиваешь?</li><li><b dir="rtl" lang="ar">مَاذَا تَقْرَأُ؟ أَقْرَأُ كِتَابًا.</b> — Что ты читаешь? Я читаю книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">بِمَ كَتَبْتَ؟</b> найдите конструкцию «حَذْفُ أَلِفِ مَا الِاسْتِفْهَامِيَّةِ», определите её роль и только затем сопоставьте с переводом: «Чем ты написал?».</div><div class="rule-note"><b>Частая ошибка.</b> Не смешивайте مَنْ для разумных лиц и مَا / مَاذَا для предметов, явлений и прочего неразумного.</div>', '6', 'rule', 'После предлога алиф вопросительного مَا удаляется: بِمَ، لِمَ، مِمَّ، عَمَّ.'),
('Мединский курс (Том 2)', '9', 'الْأَسْمَاءُ الْمَوْصُولَةُ (относительные местоимения)', '<b>Суть правила.</b> Форма выбирается по роду и числу: الَّذِي، الَّتِي، اللَّذَانِ، اللَّتَانِ، الَّذِينَ، اللَّاتِي. После нее идет поясняющее предложение.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите, кого или что заменяет местоимение.</li><li>Проверьте род и число.</li><li>Уточните позицию: отдельная форма или слитный суффикс.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ الطُّلَّابُ الَّذِينَ نَجَحُوا.</b> — Пришли студенты, которые сдали.</li><li><b dir="rtl" lang="ar">رَأَيْتُهَا وَسَأَلْتُهَا عَنِ الدَّرْسِ.</b> — Я увидел её и спросил её об уроке.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جَاءَ الطُّلَّابُ الَّذِينَ نَجَحُوا.</b> найдите конструкцию «الْأَسْمَاءُ الْمَوْصُولَةُ», определите её роль и только затем сопоставьте с переводом: «Пришли студенты, которые сдали.».</div><div class="rule-note"><b>Частая ошибка.</b> Слитное местоимение меняет функцию по контексту: оно может выражать принадлежность или дополнение.</div>', '7', 'rule', 'Форма выбирается по роду и числу: الَّذِي، الَّتِي، اللَّذَانِ، اللَّتَانِ، الَّذِينَ، اللَّاتِي. После нее идет поясняющее предложение.'),
('Мединский курс (Том 2)', '10', 'الْفِعْلُ الْمَاضِي وَالْمُضَارِعُ (прошедший и настоящее-будущее время)', '<b>Суть правила.</b> Прошедшее сообщает о завершенном действии. المضارع сообщает о настоящем или будущем и начинается одной из букв أ، ن، ي، ت.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبَ يَكْتُبُ.</b> — Он написал; он пишет.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كَتَبَ يَكْتُبُ.</b> найдите конструкцию «الْفِعْلُ الْمَاضِي وَالْمُضَارِعُ», определите её роль и только затем сопоставьте с переводом: «Он написал; он пишет.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Прошедшее сообщает о завершенном действии. المضارع сообщает о настоящем или будущем и начинается одной из букв أ، ن، ي، ت.'),
('Мединский курс (Том 2)', '10', 'إِعْرَابُ الْفِعْلِ الْمُضَارِعِ (изменение окончания المضارع)', '<b>Суть правила.</b> Настоящий глагол бывает именительным, винительным или усеченным; частица перед ним определяет окончание.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَكْتُبُ، لَنْ يَكْتُبَ، لَمْ يَكْتُبْ.</b> — Пишет; не будет писать; не писал.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">يَكْتُبُ، لَنْ يَكْتُبَ، لَمْ يَكْتُبْ.</b> найдите конструкцию «إِعْرَابُ الْفِعْلِ الْمُضَارِعِ», определите её роль и только затем сопоставьте с переводом: «Пишет; не будет писать; не писал.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '2', 'rule', 'Настоящий глагол бывает именительным, винительным или усеченным; частица перед ним определяет окончание.'),
('Мединский курс (Том 2)', '10', 'الْأَعْدَادُ الْمَعْطُوفَةُ ٢١–٩٩ (составные числа 21–99)', '<b>Суть правила.</b> Единицы соединяются с десятками через وَ. Род определяется единицей, десятки не меняются по роду; считаемое — единственное винительное.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">وَاحِدٌ وَعِشْرُونَ طَالِبًا.</b> — Двадцать один студент.</li><li><b dir="rtl" lang="ar">إِحْدَى وَعِشْرُونَ طَالِبَةً.</b> — Двадцать одна студентка.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">وَاحِدٌ وَعِشْرُونَ طَالِبًا.</b> найдите конструкцию «الْأَعْدَادُ الْمَعْطُوفَةُ ٢١–٩٩», определите её роль и только затем сопоставьте с переводом: «Двадцать один студент.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '3', 'rule', 'Единицы соединяются с десятками через وَ. Род определяется единицей, десятки не меняются по роду; считаемое — единственное винительное.'),
('Мединский курс (Том 2)', '10', 'أَبْوَابُ الْمَاضِي وَالْمُضَارِعِ (огласовочные модели I породы)', '<b>Суть правила.</b> Гласная середины المضارع словарная: فَعَلَ يَفْعُلُ, فَعَلَ يَفْعِلُ, فَعَلَ يَفْعَلُ и другие модели. Ее нужно запоминать с глаголом.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبَ يَكْتُبُ؛ جَلَسَ يَجْلِسُ؛ فَتَحَ يَفْتَحُ.</b> — Писать; сидеть; открывать.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كَتَبَ يَكْتُبُ؛ جَلَسَ يَجْلِسُ؛ فَتَحَ يَفْتَحُ.</b> найдите конструкцию «أَبْوَابُ الْمَاضِي وَالْمُضَارِعِ», определите её роль и только затем сопоставьте с переводом: «Писать; сидеть; открывать.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '4', 'rule', 'Гласная середины المضارع словарная: فَعَلَ يَفْعُلُ, فَعَلَ يَفْعِلُ, فَعَلَ يَفْعَلُ и другие модели. Ее нужно запоминать с глаголом.'),
('Мединский курс (Том 2)', '11', 'إِسْنَادُ الْمُضَارِعِ إِلَى الضَّمَائِرِ (спряжение المضارع)', '<b>Суть правила.</b> Начальная буква и окончание вместе показывают лицо: أَكْتُبُ، نَكْتُبُ، تَكْتُبُ، يَكْتُبُ. Двойственное и множественное получают ـَانِ، ـُونَ، ـِينَ، ـْنَ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُمْ يَكْتُبُونَ وَأَنْتِ تَكْتُبِينَ.</b> — Они пишут, и ты, женщина, пишешь.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُمْ يَكْتُبُونَ وَأَنْتِ تَكْتُبِينَ.</b> найдите конструкцию «إِسْنَادُ الْمُضَارِعِ إِلَى الضَّمَائِرِ», определите её роль и только затем сопоставьте с переводом: «Они пишут, и ты, женщина, пишешь.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Начальная буква и окончание вместе показывают лицо: أَكْتُبُ، نَكْتُبُ، تَكْتُبُ، يَكْتُبُ. Двойственное и множественное получают ـَانِ، ـُونَ، ـِينَ، ـْنَ.'),
('Мединский курс (Том 2)', '11', 'عَلَامَاتُ رَفْعِ الْمُضَارِعِ (признаки именительного состояния)', '<b>Суть правила.</b> Обычный المضارع имеет дамму. У пяти глагольных форм признак именительного состояния — сохранение ن.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ يَكْتُبُ؛ هُمْ يَكْتُبُونَ.</b> — Он пишет; они пишут.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُوَ يَكْتُبُ؛ هُمْ يَكْتُبُونَ.</b> найдите конструкцию «عَلَامَاتُ رَفْعِ الْمُضَارِعِ», определите её роль и только затем сопоставьте с переводом: «Он пишет; они пишут.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '2', 'rule', 'Обычный المضارع имеет дамму. У пяти глагольных форм признак именительного состояния — сохранение ن.'),
('Мединский курс (Том 2)', '11', 'مَا وَلَا النَّافِيَتَانِ وَسِينُ الِاسْتِقْبَالِ (отрицание настоящего и будущее с سَـ)', '<b>Суть правила.</b> مَا и لَا отрицают настоящее и не меняют окончание. سَـ пишется слитно с المضارع и переносит действие в будущее.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَا أَفْهَمُ هَذَا.</b> — Я не понимаю это.</li><li><b dir="rtl" lang="ar">سَأَذْهَبُ غَدًا.</b> — Я пойду завтра.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَا أَفْهَمُ هَذَا.</b> найдите конструкцию «مَا وَلَا النَّافِيَتَانِ وَسِينُ الِاسْتِقْبَالِ», определите её роль и только затем сопоставьте с переводом: «Я не понимаю это.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '3', 'rule', 'مَا и لَا отрицают настоящее и не меняют окончание. سَـ пишется слитно с المضارع и переносит действие в будущее.'),
('Мединский курс (Том 2)', '11', 'مَصْدَرُ فُعُولٍ (масдар модели فُعُول)', '<b>Суть правила.</b> Масдар на فُعُول часто образуется от глаголов движения и состояния, но масдары I породы во многом словарные.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">دَخَلَ دُخُولًا؛ خَرَجَ خُرُوجًا.</b> — Вошел — вход; вышел — выход.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">دَخَلَ دُخُولًا؛ خَرَجَ خُرُوجًا.</b> найдите конструкцию «مَصْدَرُ فُعُولٍ», определите её роль и только затем сопоставьте с переводом: «Вошел — вход; вышел — выход.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '4', 'rule', 'Масдар на فُعُول часто образуется от глаголов движения и состояния, но масдары I породы во многом словарные.'),
('Мединский курс (Том 2)', '11', 'أَمَّا ... فَـ (оборот «что касается..., то...»)', '<b>Суть правила.</b> После أَمَّا называется тема, а ответ обычно начинается с فَـ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَمَّا خَالِدٌ فَهُوَ طَبِيبٌ.</b> — Что касается Халида, то он врач.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَمَّا خَالِدٌ فَهُوَ طَبِيبٌ.</b> найдите конструкцию «أَمَّا ... فَـ», определите её роль и только затем сопоставьте с переводом: «Что касается Халида, то он врач.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '5', 'rule', 'После أَمَّا называется тема, а ответ обычно начинается с فَـ.'),
('Мединский курс (Том 2)', '11', 'أَخِي وَأَخٌ لِي («мой брат» и «один из моих братьев»)', '<b>Суть правила.</b> أَخِي определяет конкретного брата. أَخٌ لِي сообщает об одном брате без уточнения.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذَا أَخِي؛ هَذَا أَخٌ لِي.</b> — Это мой брат; это один из моих братьев.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هَذَا أَخِي؛ هَذَا أَخٌ لِي.</b> найдите конструкцию «أَخِي وَأَخٌ لِي», определите её роль и только затем сопоставьте с переводом: «Это мой брат; это один из моих братьев.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '6', 'rule', 'أَخِي определяет конкретного брата. أَخٌ لِي сообщает об одном брате без уточнения.'),
('Мединский курс (Том 2)', '12', 'وَاوُ الْجَمَاعَةِ وَيَاءُ الْمُخَاطَبَةِ وَنُونُ النِّسْوَةِ (окончания المضارع)', '<b>Суть правила.</b> Различайте يَكْتُبُونَ, تَكْتُبِينَ и يَكْتُبْنَ. У نون النسوة глагол неизменяем и перед ن стоит сукун.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُنَّ يَكْتُبْنَ وَأَنْتِ تَكْتُبِينَ.</b> — Они, женщины, пишут, и ты пишешь.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُنَّ يَكْتُبْنَ وَأَنْتِ تَكْتُبِينَ.</b> найдите конструкцию «وَاوُ الْجَمَاعَةِ وَيَاءُ الْمُخَاطَبَةِ وَنُونُ النِّسْوَةِ», определите её роль и только затем сопоставьте с переводом: «Они, женщины, пишут, и ты пишешь.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'Различайте يَكْتُبُونَ, تَكْتُبِينَ и يَكْتُبْنَ. У نون النسوة глагол неизменяем и перед ن стоит сукун.'),
('Мединский курс (Том 2)', '12', 'ظَرْفُ الزَّمَانِ (обстоятельство времени)', '<b>Суть правила.</b> Слова времени отвечают на «когда?» и часто стоят в винительном падеже: يَوْمًا، لَيْلًا، صَبَاحًا.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">سَأَزُورُكَ مَسَاءً.</b> — Я навещу тебя вечером.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">سَأَزُورُكَ مَسَاءً.</b> найдите конструкцию «ظَرْفُ الزَّمَانِ», определите её роль и только затем сопоставьте с переводом: «Я навещу тебя вечером.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'Слова времени отвечают на «когда?» и часто стоят в винительном падеже: يَوْمًا، لَيْلًا، صَبَاحًا.'),
('Мединский курс (Том 2)', '12', 'إِنَّ بَعْدَ الْقَوْلِ (إِنَّ после глагола речи)', '<b>Суть правила.</b> После самостоятельной цитаты с قَالَ обычно употребляется إِنَّ с касрой хамзы.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَالَ الْمُدَرِّسُ: إِنَّ الِامْتِحَانَ غَدًا.</b> — Учитель сказал: «Экзамен завтра».</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">قَالَ الْمُدَرِّسُ: إِنَّ الِامْتِحَانَ غَدًا.</b> найдите конструкцию «إِنَّ بَعْدَ الْقَوْلِ», определите её роль и только затем сопоставьте с переводом: «Учитель сказал: «Экзамен завтра».».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '3', 'rule', 'После самостоятельной цитаты с قَالَ обычно употребляется إِنَّ с касрой хамзы.'),
('Мединский курс (Том 2)', '13', 'إِنَّ وَأَنَّ (различие إِنَّ и أَنَّ)', '<b>Суть правила.</b> إِنَّ начинает самостоятельное высказывание или цитату. أَنَّ входит внутрь более крупной конструкции и вместе со своим предложением заменяет имя.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">عَلِمْتُ أَنَّ الدَّرْسَ سَهْلٌ.</b> — Я узнал, что урок легкий.</li><li><b dir="rtl" lang="ar">قَالَ: إِنَّ الدَّرْسَ سَهْلٌ.</b> — Он сказал: «Урок легкий».</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">عَلِمْتُ أَنَّ الدَّرْسَ سَهْلٌ.</b> найдите конструкцию «إِنَّ وَأَنَّ», определите её роль и только затем сопоставьте с переводом: «Я узнал, что урок легкий.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'إِنَّ начинает самостоятельное высказывание или цитату. أَنَّ входит внутрь более крупной конструкции и вместе со своим предложением заменяет имя.'),
('Мединский курс (Том 2)', '13', 'مُرَاجَعَةُ تَصْرِيفِ الْمُضَارِعِ (повторение спряжения المضارع)', '<b>Суть правила.</b> Проверяйте форму в три шага: начальная буква лица, основа глагола, окончание числа и рода.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَنَا أَدْرُسُ، نَحْنُ نَدْرُسُ، هُمْ يَدْرُسُونَ.</b> — Я учусь, мы учимся, они учатся.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَنَا أَدْرُسُ، نَحْنُ نَدْرُسُ، هُمْ يَدْرُسُونَ.</b> найдите конструкцию «مُرَاجَعَةُ تَصْرِيفِ الْمُضَارِعِ», определите её роль и только затем сопоставьте с переводом: «Я учусь, мы учимся, они учатся.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '2', 'rule', 'Проверяйте форму в три шага: начальная буква лица, основа глагола, окончание числа и рода.'),
('Мединский курс (Том 2)', '14', 'فِعْلُ الْأَمْرِ (повелительное наклонение)', '<b>Суть правила.</b> Повелительная форма строится для второго лица от усеченной формы المضارع: убирается تَـ, а при невозможности начать с сукуна добавляется همزة الوصل.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">تَكْتُبُ ← لَمْ تَكْتُبْ ← اُكْتُبْ.</b> — Ты пишешь → ты не писал → пиши.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">تَكْتُبُ ← لَمْ تَكْتُبْ ← اُكْتُبْ.</b> найдите конструкцию «فِعْلُ الْأَمْرِ», определите её роль и только затем сопоставьте с переводом: «Ты пишешь → ты не писал → пиши.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Повелительная форма строится для второго лица от усеченной формы المضارع: убирается تَـ, а при невозможности начать с сукуна добавляется همزة الوصل.'),
('Мединский курс (Том 2)', '14', 'هَمْزَةُ الْوَصْلِ فِي الْأَمْرِ الثُّلَاثِيِّ (соединительная хамза)', '<b>Суть правила.</b> Огласовка начальной хамзы зависит от гласной середины المضارع: при дамме обычно اُ, иначе اِ.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَكْتُبُ: اُكْتُبْ؛ يَجْلِسُ: اِجْلِسْ.</b> — Пиши; сядь.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">يَكْتُبُ: اُكْتُبْ؛ يَجْلِسُ: اِجْلِسْ.</b> найдите конструкцию «هَمْزَةُ الْوَصْلِ فِي الْأَمْرِ الثُّلَاثِيِّ», определите её роль и только затем сопоставьте с переводом: «Пиши; сядь.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '2', 'rule', 'Огласовка начальной хамзы зависит от гласной середины المضارع: при дамме обычно اُ, иначе اِ.'),
('Мединский курс (Том 2)', '14', 'تَصْرِيفُ الْأَمْرِ وَبِنَاؤُهُ (пять форм повелительного)', '<b>Суть правила.</b> Формы второго лица: اُكْتُبْ، اُكْتُبَا، اُكْتُبُوا، اُكْتُبِي، اُكْتُبْنَ. Они строятся на сукуне, удалении ن или слабой буквы.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">اُدْخُلُوا الْفَصْلَ.</b> — Войдите в класс.</li><li><b dir="rtl" lang="ar">اُكْتُبْنَ الدَّرْسَ.</b> — Пишите урок, женщины.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">اُدْخُلُوا الْفَصْلَ.</b> найдите конструкцию «تَصْرِيفُ الْأَمْرِ وَبِنَاؤُهُ», определите её роль и только затем сопоставьте с переводом: «Войдите в класс.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '3', 'rule', 'Формы второго лица: اُكْتُبْ، اُكْتُبَا، اُكْتُبُوا، اُكْتُبِي، اُكْتُبْنَ. Они строятся на сукуне, удалении ن или слабой буквы.'),
('Мединский курс (Том 2)', '15', 'لَا النَّاهِيَةُ (запретительная لَا)', '<b>Суть правила.</b> لَا النَّاهِيَةُ означает «не делай» и переводит المضارع в усеченное состояние.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَا تَذْهَبْ.</b> — Не уходи.</li><li><b dir="rtl" lang="ar">لَا تَكْتُبُوا.</b> — Не пишите.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَا تَذْهَبْ.</b> найдите конструкцию «لَا النَّاهِيَةُ», определите её роль и только затем сопоставьте с переводом: «Не уходи.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '1', 'rule', 'لَا النَّاهِيَةُ означает «не делай» и переводит المضارع в усеченное состояние.'),
('Мединский курс (Том 2)', '15', 'لَا النَّافِيَةُ وَلَا النَّاهِيَةُ (отрицательная и запретительная لَا)', '<b>Суть правила.</b> Отрицательная لَا сообщает факт и оставляет глагол именительным; запретительная обращена к собеседнику и усекает глагол.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَا يَذْهَبُ حَامِدٌ؛ لَا تَذْهَبْ يَا حَامِدُ.</b> — Хамид не идет; не уходи, Хамид.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَا يَذْهَبُ حَامِدٌ؛ لَا تَذْهَبْ يَا حَامِدُ.</b> найдите конструкцию «لَا النَّافِيَةُ وَلَا النَّاهِيَةُ», определите её роль и только затем сопоставьте с переводом: «Хамид не идет; не уходи, Хамид.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '2', 'rule', 'Отрицательная لَا сообщает факт и оставляет глагол именительным; запретительная обращена к собеседнику и усекает глагол.'),
('Мединский курс (Том 2)', '15', 'كَادَ («едва не, почти»)', '<b>Суть правила.</b> كَادَ — ناقصный глагол. Его имя именительное, а сказуемое обычно выражено المضارع без أَنْ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَادَ الطِّفْلُ يَسْقُطُ.</b> — Ребенок едва не упал.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كَادَ الطِّفْلُ يَسْقُطُ.</b> найдите конструкцию «كَادَ», определите её роль и только затем сопоставьте с переводом: «Ребенок едва не упал.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'كَادَ — ناقصный глагол. Его имя именительное, а сказуемое обычно выражено المضارع без أَنْ.'),
('Мединский курс (Том 2)', '15', 'مُرَاجَعَةُ التَّعَجُّبِ (повторение восклицательной модели)', '<b>Суть правила.</b> В модели مَا أَفْعَلَ объект впечатления стоит в винительном.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا أَحْسَنَ هَذَا الْكِتَابَ!</b> — Как хороша эта книга!</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">مَا أَحْسَنَ هَذَا الْكِتَابَ!</b> найдите конструкцию «مُرَاجَعَةُ التَّعَجُّبِ», определите её роль и только затем сопоставьте с переводом: «Как хороша эта книга!».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '4', 'rule', 'В модели مَا أَفْعَلَ объект впечатления стоит в винительном.'),
('Мединский курс (Том 2)', '16', 'إِسْنَادُ يُرِيدُ وَالْمَصْدَرُ الْمُؤَوَّلُ (спряжение «хотеть» и أَنْ + глагол)', '<b>Суть правила.</b> У أَرَادَ المضارع имеет основу رِيد: أُرِيدُ، نُرِيدُ، تُرِيدُ، يُرِيدُ. أَنْ + المضارع является смысловым эквивалентом масдара.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أُرِيدُ أَنْ أَتَعَلَّمَ = أُرِيدُ التَّعَلُّمَ.</b> — Я хочу учиться = я хочу обучения.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أُرِيدُ أَنْ أَتَعَلَّمَ = أُرِيدُ التَّعَلُّمَ.</b> найдите конструкцию «إِسْنَادُ يُرِيدُ وَالْمَصْدَرُ الْمُؤَوَّلُ», определите её роль и только затем сопоставьте с переводом: «Я хочу учиться = я хочу обучения.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'У أَرَادَ المضارع имеет основу رِيد: أُرِيدُ، نُرِيدُ، تُرِيدُ، يُرِيدُ. أَنْ + المضارع является смысловым эквивалентом масдара.'),
('Мединский курс (Том 2)', '16', 'مَا الْمَوْصُولَةُ (относительное مَا «то, что»)', '<b>Суть правила.</b> مَا может означать «то, что» и связывать главное предложение с поясняющим.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَفْهَمُ مَا تَقُولُ.</b> — Я понимаю то, что ты говоришь.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَفْهَمُ مَا تَقُولُ.</b> найдите конструкцию «مَا الْمَوْصُولَةُ», определите её роль и только затем сопоставьте с переводом: «Я понимаю то, что ты говоришь.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'مَا может означать «то, что» и связывать главное предложение с поясняющим.'),
('Мединский курс (Том 2)', '16', 'أَلْوَانُ أَفْعَلَ وَفَعْلَاءُ (цвета мужского и женского рода)', '<b>Суть правила.</b> Цвета часто имеют мужскую модель أَفْعَلُ и женскую فَعْلَاءُ; такие слова обычно ممنوع من الصرف.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَمِيصٌ أَبْيَضُ وَسَيَّارَةٌ بَيْضَاءُ.</b> — Белая рубашка и белый автомобиль.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">قَمِيصٌ أَبْيَضُ وَسَيَّارَةٌ بَيْضَاءُ.</b> найдите конструкцию «أَلْوَانُ أَفْعَلَ وَفَعْلَاءُ», определите её роль и только затем сопоставьте с переводом: «Белая рубашка и белый автомобиль.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '3', 'rule', 'Цвета часто имеют мужскую модель أَفْعَلُ и женскую فَعْلَاءُ; такие слова обычно ممنوع من الصرف.'),
('Мединский курс (Том 2)', '16', 'الْعَلَمُ الْمَعْدُولُ وَعُمَرُ وَعَمْرٌو (особые собственные имена)', '<b>Суть правила.</b> Некоторые имена, включая عُمَرُ, не получают танвин и имеют фатху в родительном без ال/идафы. В عَمْرٌو буква و пишется для отличия, но обычно не произносится.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">سَلَّمْتُ عَلَى عُمَرَ؛ جَاءَ عَمْرٌو.</b> — Я поприветствовал Умара; Амр пришел.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">سَلَّمْتُ عَلَى عُمَرَ؛ جَاءَ عَمْرٌو.</b> найдите конструкцию «الْعَلَمُ الْمَعْدُولُ وَعُمَرُ وَعَمْرٌو», определите её роль и только затем сопоставьте с переводом: «Я поприветствовал Умара; Амр пришел.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '4', 'rule', 'Некоторые имена, включая عُمَرُ, не получают танвин и имеют фатху в родительном без ال/идафы. В عَمْرٌو буква و пишется для отличия, но обычно не произносится.'),
('Мединский курс (Том 2)', '16', 'آخَرُ وَأُخْرَى وَغَيْرُ («другой» и «иной, кроме»)', '<b>Суть правила.</b> آخَرُ/أُخْرَى согласуется как прилагательное. غَيْرُ обычно входит в идафу и получает падеж по своей роли.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أُرِيدُ كِتَابًا آخَرَ.</b> — Я хочу другую книгу.</li><li><b dir="rtl" lang="ar">جَاءَ غَيْرُ خَالِدٍ.</b> — Пришел не Халид.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أُرِيدُ كِتَابًا آخَرَ.</b> найдите конструкцию «آخَرُ وَأُخْرَى وَغَيْرُ», определите её роль и только затем сопоставьте с переводом: «Я хочу другую книгу.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '5', 'rule', 'آخَرُ/أُخْرَى согласуется как прилагательное. غَيْرُ обычно входит в идафу и получает падеж по своей роли.'),
('Мединский курс (Том 2)', '16', 'إِعْرَابُ ذُو (склонение ذُو)', '<b>Суть правила.</b> Как одно из пяти имен ذُو меняется буквами: ذُو в именительном, ذَا в винительном, ذِي в родительном.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите синтаксическую роль слова.</li><li>Выберите требуемый падеж.</li><li>Проверьте окончание с учётом числа и типа имени.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَأَيْتُ رَجُلًا ذَا عِلْمٍ.</b> — Я увидел знающего человека.</li><li><b dir="rtl" lang="ar">جَاءَ الطَّالِبُ وَرَأَيْتُ الطَّالِبَ وَسَلَّمْتُ عَلَى الطَّالِبِ.</b> — Ученик пришёл; я увидел ученика и поприветствовал ученика.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">رَأَيْتُ رَجُلًا ذَا عِلْمٍ.</b> найдите конструкцию «إِعْرَابُ ذُو», определите её роль и только затем сопоставьте с переводом: «Я увидел знающего человека.».</div><div class="rule-note"><b>Частая ошибка.</b> Окончание зависит не только от смысла, но и от позиции слова в предложении.</div>', '6', 'rule', 'Как одно из пяти имен ذُو меняется буквами: ذُو в именительном, ذَا в винительном, ذِي в родительном.'),
('Мединский курс (Том 2)', '17', 'نَوَاصِبُ الْمُضَارِعِ (частицы винительного состояния)', '<b>Суть правила.</b> أَنْ، لَنْ и لام التعليل ставят المضارع в винительное состояние. У обычной формы появляется фатха, у пяти глаголов удаляется ن.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أُرِيدُ أَنْ أَذْهَبَ؛ لَنْ أَتَأَخَّرَ.</b> — Я хочу пойти; я не опоздаю.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أُرِيدُ أَنْ أَذْهَبَ؛ لَنْ أَتَأَخَّرَ.</b> найдите конструкцию «نَوَاصِبُ الْمُضَارِعِ», определите её роль и только затем сопоставьте с переводом: «Я хочу пойти; я не опоздаю.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'أَنْ، لَنْ и لام التعليل ставят المضارع в винительное состояние. У обычной формы появляется фатха, у пяти глаголов удаляется ن.'),
('Мединский курс (Том 2)', '17', 'أَنْ وَلَنْ وَلَامُ التَّعْلِيلِ («чтобы», «не будет» и لام цели)', '<b>Суть правила.</b> أَنْ связывает действия, لَنْ отрицает будущее, لِـ перед глаголом означает цель. Во всех случаях المضارع منصوب.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جِئْتُ لِأَتَعَلَّمَ.</b> — Я пришел, чтобы учиться.</li><li><b dir="rtl" lang="ar">لَنْ نَغِيبَ غَدًا.</b> — Мы не будем отсутствовать завтра.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جِئْتُ لِأَتَعَلَّمَ.</b> найдите конструкцию «أَنْ وَلَنْ وَلَامُ التَّعْلِيلِ», определите её роль и только затем сопоставьте с переводом: «Я пришел, чтобы учиться.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '2', 'rule', 'أَنْ связывает действия, لَنْ отрицает будущее, لِـ перед глаголом означает цель. Во всех случаях المضارع منصوب.'),
('Мединский курс (Том 2)', '17', 'عَلَامَاتُ نَصْبِ الْمُضَارِعِ (признаки винительного состояния)', '<b>Суть правила.</b> Признак — явная или предполагаемая фатха; у الأفعال الخمسة — удаление ن.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَنْ يَكْتُبُوا.</b> — Они не будут писать.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَنْ يَكْتُبُوا.</b> найдите конструкцию «عَلَامَاتُ نَصْبِ الْمُضَارِعِ», определите её роль и только затем сопоставьте с переводом: «Они не будут писать.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '3', 'rule', 'Признак — явная или предполагаемая фатха; у الأفعال الخمسة — удаление ن.'),
('Мединский курс (Том 2)', '17', 'يُمْكِنُ وَمُنْذُ («возможно» и «с тех пор»)', '<b>Суть правила.</b> يُمْكِنُ часто вводит أَنْ + глагол. مُنْذُ указывает начальную точку или длительность времени.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يُمْكِنُ أَنْ نَبْدَأَ؛ مَا رَأَيْتُهُ مُنْذُ أُسْبُوعٍ.</b> — Мы можем начать; я не видел его неделю.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">يُمْكِنُ أَنْ نَبْدَأَ؛ مَا رَأَيْتُهُ مُنْذُ أُسْبُوعٍ.</b> найдите конструкцию «يُمْكِنُ وَمُنْذُ», определите её роль и только затем сопоставьте с переводом: «Мы можем начать; я не видел его неделю.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '4', 'rule', 'يُمْكِنُ часто вводит أَنْ + глагол. مُنْذُ указывает начальную точку или длительность времени.'),
('Мединский курс (Том 2)', '17', 'رَأَى يَرَى (особое спряжение «видеть»)', '<b>Суть правила.</b> В المضارع хамза основы исчезает: رَأَى → يَرَى، أَرَى، نَرَى، تَرَى.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَرَى الْقَمَرَ.</b> — Я вижу луну.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَرَى الْقَمَرَ.</b> найдите конструкцию «رَأَى يَرَى», определите её роль и только затем сопоставьте с переводом: «Я вижу луну.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '5', 'rule', 'В المضارع хамза основы исчезает: رَأَى → يَرَى، أَرَى، نَرَى، تَرَى.'),
('Мединский курс (Том 2)', '18', 'حَذْفُ النُّونِ مِنَ الْأَفْعَالِ الْخَمْسَةِ (удаление ن у пяти форм)', '<b>Суть правила.</b> После винительных и усечных частиц формы ـانِ، ـونَ، ـينَ теряют ن.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَنْ تَكْتُبُوا؛ لَمْ تَكْتُبُوا.</b> — Вы не будете писать; вы не писали.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَنْ تَكْتُبُوا؛ لَمْ تَكْتُبُوا.</b> найдите конструкцию «حَذْفُ النُّونِ مِنَ الْأَفْعَالِ الْخَمْسَةِ», определите её роль и только затем сопоставьте с переводом: «Вы не будете писать; вы не писали.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'После винительных и усечных частиц формы ـانِ، ـونَ، ـينَ теряют ن.'),
('Мединский курс (Том 2)', '18', 'نُونُ النِّسْوَةِ مَعَ الْمُضَارِعِ (женская ن в المضارع)', '<b>Суть правила.</b> Форма с نون النسوة строится на сукуне и не меняется после частиц винительного или усеченного состояния.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُنَّ يَكْتُبْنَ؛ لَنْ يَكْتُبْنَ.</b> — Они пишут; они не будут писать.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُنَّ يَكْتُبْنَ؛ لَنْ يَكْتُبْنَ.</b> найдите конструкцию «نُونُ النِّسْوَةِ مَعَ الْمُضَارِعِ», определите её роль и только затем сопоставьте с переводом: «Они пишут; они не будут писать.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '2', 'rule', 'Форма с نون النسوة строится на сукуне и не меняется после частиц винительного или усеченного состояния.'),
('Мединский курс (Том 2)', '18', 'أَلَّا (слитное أَنْ لَا)', '<b>Суть правила.</b> أَلَّا образуется из أَنْ + لَا. Глагол после нее остается в винительном состоянии.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أُرِيدُ أَلَّا تَتَأَخَّرَ.</b> — Я хочу, чтобы ты не опаздывал.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أُرِيدُ أَلَّا تَتَأَخَّرَ.</b> найдите конструкцию «أَلَّا», определите её роль и только затем сопоставьте с переводом: «Я хочу, чтобы ты не опаздывал.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '3', 'rule', 'أَلَّا образуется из أَنْ + لَا. Глагол после нее остается в винительном состоянии.'),
('Мединский курс (Том 2)', '18', 'كَافُ التَّشْبِيهِ (предлог сравнения كَـ)', '<b>Суть правила.</b> كَـ означает «как, подобно» и ставит следующее имя в родительный падеж.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ كَالْأَسَدِ.</b> — Он как лев.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُوَ كَالْأَسَدِ.</b> найдите конструкцию «كَافُ التَّشْبِيهِ», определите её роль и только затем сопоставьте с переводом: «Он как лев.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '4', 'rule', 'كَـ означает «как, подобно» и ставит следующее имя в родительный падеж.'),
('Мединский курс (Том 2)', '18', 'الْأَفْعَالُ الْخَمْسَةُ (пять глагольных форм)', '<b>Суть правила.</b> Это المضارع с ألف الاثنين, واو الجماعة или ياء المخاطبة. Они именительны с сохранением ن и винительны/усечены с ее удалением.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُمَا يَكْتُبَانِ، هُمْ يَكْتُبُونَ، أَنْتِ تَكْتُبِينَ.</b> — Они двое пишут, они пишут, ты пишешь.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُمَا يَكْتُبَانِ، هُمْ يَكْتُبُونَ، أَنْتِ تَكْتُبِينَ.</b> найдите конструкцию «الْأَفْعَالُ الْخَمْسَةُ», определите её роль и только затем сопоставьте с переводом: «Они двое пишут, они пишут, ты пишешь.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '5', 'rule', 'Это المضارع с ألف الاثنين, واو الجماعة или ياء المخاطبة. Они именительны с сохранением ن и винительны/усечены с ее удалением.'),
('Мединский курс (Том 2)', '19', 'نَفْيُ الْمَاضِي وَالْحَالِ وَالْمُسْتَقْبَلِ (отрицание трех времен)', '<b>Суть правила.</b> Прошедшее отрицают مَا или لَمْ + المضارع, настоящее — لَا/مَا + المضارع, будущее — لَنْ + المضارع.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا ذَهَبَ؛ لَا يَذْهَبُ؛ لَنْ يَذْهَبَ.</b> — Не пошел; не идет; не пойдет.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">مَا ذَهَبَ؛ لَا يَذْهَبُ؛ لَنْ يَذْهَبَ.</b> найдите конструкцию «نَفْيُ الْمَاضِي وَالْحَالِ وَالْمُسْتَقْبَلِ», определите её роль и только затем сопоставьте с переводом: «Не пошел; не идет; не пойдет.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '1', 'rule', 'Прошедшее отрицают مَا или لَمْ + المضارع, настоящее — لَا/مَا + المضارع, будущее — لَنْ + المضارع.'),
('Мединский курс (Том 2)', '19', 'قَطُّ وَأَبَدًا («никогда» в прошлом и будущем)', '<b>Суть правила.</b> قَطُّ обычно усиливает отрицание прошлого, أَبَدًا — отрицание будущего или общее отрицание.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا رَأَيْتُهُ قَطُّ؛ لَنْ أَنْسَاهُ أَبَدًا.</b> — Я никогда его не видел; я никогда его не забуду.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">مَا رَأَيْتُهُ قَطُّ؛ لَنْ أَنْسَاهُ أَبَدًا.</b> найдите конструкцию «قَطُّ وَأَبَدًا», определите её роль и только затем сопоставьте с переводом: «Я никогда его не видел; я никогда его не забуду.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'قَطُّ обычно усиливает отрицание прошлого, أَبَدًا — отрицание будущего или общее отрицание.'),
('Мединский курс (Том 2)', '20', 'الْمُثَنَّى وَإِعْرَابُهُ (двойственное число и его падежи)', '<b>Суть правила.</b> Двойственное получает ـَانِ в именительном и ـَيْنِ в винительном/родительном. ن удаляется в идафе.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ طَالِبَانِ؛ رَأَيْتُ طَالِبَيْنِ.</b> — Пришли два студента; я увидел двух студентов.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جَاءَ طَالِبَانِ؛ رَأَيْتُ طَالِبَيْنِ.</b> найдите конструкцию «الْمُثَنَّى وَإِعْرَابُهُ», определите её роль и только затем сопоставьте с переводом: «Пришли два студента; я увидел двух студентов.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '1', 'rule', 'Двойственное получает ـَانِ в именительном и ـَيْنِ в винительном/родительном. ن удаляется в идафе.'),
('Мединский курс (Том 2)', '20', 'أَحَدُهُمَا وَالْآخَرُ («один из них и другой»)', '<b>Суть правила.</b> أَحَدُهُمَا относится к одному из двух, الْآخَرُ — ко второму; обе формы получают падеж по роли.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَحَدُهُمَا طَبِيبٌ وَالْآخَرُ مُهَنْدِسٌ.</b> — Один из них врач, другой инженер.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَحَدُهُمَا طَبِيبٌ وَالْآخَرُ مُهَنْدِسٌ.</b> найдите конструкцию «أَحَدُهُمَا وَالْآخَرُ», определите её роль и только затем сопоставьте с переводом: «Один из них врач, другой инженер.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'أَحَدُهُمَا относится к одному из двух, الْآخَرُ — ко второму; обе формы получают падеж по роли.'),
('Мединский курс (Том 2)', '20', 'إِعْرَابُ ذُو وَذَاتُ (склонение ذُو и ذَاتُ)', '<b>Суть правила.</b> ذُو имеет формы ذُو/ذَا/ذِي по трем падежам. ذَاتُ склоняется обычными огласовками и согласуется в роде.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите синтаксическую роль слова.</li><li>Выберите требуемый падеж.</li><li>Проверьте окончание с учётом числа и типа имени.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَرَرْتُ بِرَجُلٍ ذِي عِلْمٍ.</b> — Я прошел мимо знающего человека.</li><li><b dir="rtl" lang="ar">جَاءَ الطَّالِبُ وَرَأَيْتُ الطَّالِبَ وَسَلَّمْتُ عَلَى الطَّالِبِ.</b> — Ученик пришёл; я увидел ученика и поприветствовал ученика.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">مَرَرْتُ بِرَجُلٍ ذِي عِلْمٍ.</b> найдите конструкцию «إِعْرَابُ ذُو وَذَاتُ», определите её роль и только затем сопоставьте с переводом: «Я прошел мимо знающего человека.».</div><div class="rule-note"><b>Частая ошибка.</b> Окончание зависит не только от смысла, но и от позиции слова в предложении.</div>', '3', 'rule', 'ذُو имеет формы ذُو/ذَا/ذِي по трем падежам. ذَاتُ склоняется обычными огласовками и согласуется в роде.'),
('Мединский курс (Том 2)', '21', 'لَمْ وَلَمَّا (отрицательные усеченные частицы)', '<b>Суть правила.</b> Обе частицы усекают المضارع и относят отрицание к прошлому. لَمَّا добавляет «еще не» с ожиданием действия.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَمْ يَصِلْ؛ لَمَّا يَصِلْ.</b> — Он не прибыл; он еще не прибыл.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَمْ يَصِلْ؛ لَمَّا يَصِلْ.</b> найдите конструкцию «لَمْ وَلَمَّا», определите её роль и только затем сопоставьте с переводом: «Он не прибыл; он еще не прибыл.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '1', 'rule', 'Обе частицы усекают المضارع и относят отрицание к прошлому. لَمَّا добавляет «еще не» с ожиданием действия.'),
('Мединский курс (Том 2)', '21', 'عَلَامَاتُ جَزْمِ الْمُضَارِعِ (признаки усеченного состояния)', '<b>Суть правила.</b> Признак — сукун, удаление слабой последней буквы или удаление ن у пяти форм.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَمْ يَكْتُبْ؛ لَمْ يَمْشِ؛ لَمْ يَكْتُبُوا.</b> — Не писал; не шел; они не писали.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَمْ يَكْتُبْ؛ لَمْ يَمْشِ؛ لَمْ يَكْتُبُوا.</b> найдите конструкцию «عَلَامَاتُ جَزْمِ الْمُضَارِعِ», определите её роль и только затем сопоставьте с переводом: «Не писал; не шел; они не писали.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '2', 'rule', 'Признак — сукун, удаление слабой последней буквы или удаление ن у пяти форм.'),
('Мединский курс (Том 2)', '21', 'أَقْسَامُ الْكَلِمَةِ (три части речи)', '<b>Суть правила.</b> Арабское слово относится к имени اِسْمٌ, глаголу فِعْلٌ или частице حَرْفٌ. У каждой группы свои признаки.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كِتَابٌ اسم، كَتَبَ فعل، فِي حرف.</b> — «Книга» — имя, «написал» — глагол, «в» — частица.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كِتَابٌ اسم، كَتَبَ فعل، فِي حرف.</b> найдите конструкцию «أَقْسَامُ الْكَلِمَةِ», определите её роль и только затем сопоставьте с переводом: ««Книга» — имя, «написал» — глагол, «в» — частица.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'Арабское слово относится к имени اِسْمٌ, глаголу فِعْلٌ или частице حَرْفٌ. У каждой группы свои признаки.'),
('Мединский курс (Том 2)', '21', 'الْجُمْلَةُ الِاسْمِيَّةُ وَالْفِعْلِيَّةُ (именное и глагольное предложение)', '<b>Суть правила.</b> Именное начинается именем и обычно содержит مبتدأ/خبر. Глагольное начинается глаголом, затем идет исполнитель и при необходимости дополнение.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ؛ كَتَبَ الطَّالِبُ الدَّرْسَ.</b> — Студент усердный; студент написал урок.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ؛ كَتَبَ الطَّالِبُ الدَّرْسَ.</b> найдите конструкцию «الْجُمْلَةُ الِاسْمِيَّةُ وَالْفِعْلِيَّةُ», определите её роль и только затем сопоставьте с переводом: «Студент усердный; студент написал урок.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '4', 'rule', 'Именное начинается именем и обычно содержит مبتدأ/خبر. Глагольное начинается глаголом, затем идет исполнитель и при необходимости дополнение.'),
('Мединский курс (Том 2)', '21', 'اللَّاتِي وَاللَّائِي (женское множественное относительное местоимение)', '<b>Суть правила.</b> Обе формы употребляются для группы женского рода и вводят поясняющее предложение.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите, кого или что заменяет местоимение.</li><li>Проверьте род и число.</li><li>Уточните позицию: отдельная форма или слитный суффикс.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَتِ الطَّالِبَاتُ اللَّاتِي نَجَحْنَ.</b> — Пришли студентки, которые сдали.</li><li><b dir="rtl" lang="ar">رَأَيْتُهَا وَسَأَلْتُهَا عَنِ الدَّرْسِ.</b> — Я увидел её и спросил её об уроке.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جَاءَتِ الطَّالِبَاتُ اللَّاتِي نَجَحْنَ.</b> найдите конструкцию «اللَّاتِي وَاللَّائِي», определите её роль и только затем сопоставьте с переводом: «Пришли студентки, которые сдали.».</div><div class="rule-note"><b>Частая ошибка.</b> Слитное местоимение меняет функцию по контексту: оно может выражать принадлежность или дополнение.</div>', '5', 'rule', 'Обе формы употребляются для группы женского рода и вводят поясняющее предложение.'),
('Мединский курс (Том 2)', '22', 'حَالَاتُ الْمُضَارِعِ الثَّلَاثُ (три состояния المضارع)', '<b>Суть правила.</b> Без управляющей частицы глагол مرفوع: يَكْتُبُ. После أَنْ/لَنْ/لِـ он منصوب: يَكْتُبَ. После لَمْ/لَمَّا/لَا الناهية он مجزوم: يَكْتُبْ.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ يَدْرُسُ؛ لَنْ يَدْرُسَ؛ لَمْ يَدْرُسْ.</b> — Он учится; не будет учиться; не учился.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُوَ يَدْرُسُ؛ لَنْ يَدْرُسَ؛ لَمْ يَدْرُسْ.</b> найдите конструкцию «حَالَاتُ الْمُضَارِعِ الثَّلَاثُ», определите её роль и только затем сопоставьте с переводом: «Он учится; не будет учиться; не учился.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div><div class="rule-note"><b>Самопроверка.</b> Сначала найдите частицу перед глаголом, затем определите состояние и только после этого выбирайте окончание.</div>', '1', 'rule', 'Без управляющей частицы глагол مرفوع: يَكْتُبُ. После أَنْ/لَنْ/لِـ он منصوب: يَكْتُبَ. После لَمْ/لَمَّا/لَا الناهية он مجزوم: يَكْتُبْ.'),
('Мединский курс (Том 2)', '23', 'إِعْرَابُ جَمْعِ الْمُذَكَّرِ السَّالِمِ (падежи правильного мужского множественного)', '<b>Суть правила.</b> Окончание ـُونَ используется в именительном, ـِينَ — в винительном и родительном. ن удаляется в идафе.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите синтаксическую роль слова.</li><li>Выберите требуемый падеж.</li><li>Проверьте окончание с учётом числа и типа имени.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُونَ؛ رَأَيْتُ الْمُدَرِّسِينَ.</b> — Пришли учителя; я увидел учителей.</li><li><b dir="rtl" lang="ar">جَاءَ الطَّالِبُ وَرَأَيْتُ الطَّالِبَ وَسَلَّمْتُ عَلَى الطَّالِبِ.</b> — Ученик пришёл; я увидел ученика и поприветствовал ученика.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُونَ؛ رَأَيْتُ الْمُدَرِّسِينَ.</b> найдите конструкцию «إِعْرَابُ جَمْعِ الْمُذَكَّرِ السَّالِمِ», определите её роль и только затем сопоставьте с переводом: «Пришли учителя; я увидел учителей.».</div><div class="rule-note"><b>Частая ошибка.</b> Окончание зависит не только от смысла, но и от позиции слова в предложении.</div>', '1', 'rule', 'Окончание ـُونَ используется в именительном, ـِينَ — в винительном и родительном. ن удаляется в идафе.'),
('Мединский курс (Том 2)', '23', 'إِعْرَابُ أَلْفَاظِ الْعُقُودِ (склонение десятков)', '<b>Суть правила.</b> عِشْرُونَ–تِسْعُونَ имеют те же падежные окончания, что и правильное мужское множественное.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">فِي الْفَصْلِ ثَلَاثُونَ طَالِبًا؛ رَأَيْتُ ثَلَاثِينَ.</b> — В классе тридцать студентов; я увидел тридцать.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">فِي الْفَصْلِ ثَلَاثُونَ طَالِبًا؛ رَأَيْتُ ثَلَاثِينَ.</b> найдите конструкцию «إِعْرَابُ أَلْفَاظِ الْعُقُودِ», определите её роль и только затем сопоставьте с переводом: «В классе тридцать студентов; я увидел тридцать.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '2', 'rule', 'عِشْرُونَ–تِسْعُونَ имеют те же падежные окончания, что и правильное мужское множественное.'),
('Мединский курс (Том 2)', '23', 'نَفْيُ الْمَاضِي بِـلَا (отрицание повторяющегося прошлого через لَا)', '<b>Суть правила.</b> لَا может повторяться перед прошедшими глаголами, когда перечисляется то, чего не произошло.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَا أَكَلَ وَلَا شَرِبَ.</b> — Он не ел и не пил.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَا أَكَلَ وَلَا شَرِبَ.</b> найдите конструкцию «نَفْيُ الْمَاضِي بِـلَا», определите её роль и только затем сопоставьте с переводом: «Он не ел и не пил.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '3', 'rule', 'لَا может повторяться перед прошедшими глаголами, когда перечисляется то, чего не произошло.'),
('Мединский курс (Том 2)', '24', 'الْعَدَدَانِ ١ وَ٢ (числа один и два)', '<b>Суть правила.</b> Они согласуются с существительным и обычно стоят после него как прилагательные; для двух часто достаточно двойственной формы.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">طَالِبٌ وَاحِدٌ؛ طَالِبَتَانِ اثْنَتَانِ.</b> — Один студент; две студентки.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">طَالِبٌ وَاحِدٌ؛ طَالِبَتَانِ اثْنَتَانِ.</b> найдите конструкцию «الْعَدَدَانِ ١ وَ٢», определите её роль и только затем сопоставьте с переводом: «Один студент; две студентки.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '1', 'rule', 'Они согласуются с существительным и обычно стоят после него как прилагательные; для двух часто достаточно двойственной формы.'),
('Мединский курс (Том 2)', '24', 'الْأَعْدَادُ ٣–١٠ (числа 3–10)', '<b>Суть правила.</b> Число противоположно считаемому по роду, а считаемое стоит во множественном родительном.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ثَلَاثَةُ كُتُبٍ؛ ثَلَاثُ سَيَّارَاتٍ.</b> — Три книги; три автомобиля.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">ثَلَاثَةُ كُتُبٍ؛ ثَلَاثُ سَيَّارَاتٍ.</b> найдите конструкцию «الْأَعْدَادُ ٣–١٠», определите её роль и только затем сопоставьте с переводом: «Три книги; три автомобиля.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '2', 'rule', 'Число противоположно считаемому по роду, а считаемое стоит во множественном родительном.'),
('Мединский курс (Том 2)', '24', 'الْأَعْدَادُ ١١–١٩ (числа 11–19)', '<b>Суть правила.</b> В 11 и 12 обе части согласуются. В 13–19 первая часть противоположна роду, عَشَر/عَشْرَة согласуется; считаемое единственное винительное.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَحَدَ عَشَرَ طَالِبًا؛ خَمْسَ عَشْرَةَ امْرَأَةً.</b> — Одиннадцать студентов; пятнадцать женщин.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَحَدَ عَشَرَ طَالِبًا؛ خَمْسَ عَشْرَةَ امْرَأَةً.</b> найдите конструкцию «الْأَعْدَادُ ١١–١٩», определите её роль и только затем сопоставьте с переводом: «Одиннадцать студентов; пятнадцать женщин.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '3', 'rule', 'В 11 и 12 обе части согласуются. В 13–19 первая часть противоположна роду, عَشَر/عَشْرَة согласуется; считаемое единственное винительное.'),
('Мединский курс (Том 2)', '24', 'أَلْفَاظُ الْعُقُودِ وَالْمَعْطُوفُ (десятки и составные числа)', '<b>Суть правила.</b> Десятки склоняются через و/ي, единица соединяется с ними через وَ. Считаемое всегда единственное винительное.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ثَلَاثَةٌ وَعِشْرُونَ كِتَابًا.</b> — Двадцать три книги.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">ثَلَاثَةٌ وَعِشْرُونَ كِتَابًا.</b> найдите конструкцию «أَلْفَاظُ الْعُقُودِ وَالْمَعْطُوفُ», определите её роль и только затем сопоставьте с переводом: «Двадцать три книги.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '4', 'rule', 'Десятки склоняются через و/ي, единица соединяется с ними через وَ. Считаемое всегда единственное винительное.'),
('Мединский курс (Том 2)', '24', 'الْمِئَاتُ وَالْآلَافُ (сотни и тысячи)', '<b>Суть правила.</b> После сотен и тысяч считаемое единственное родительное. В 300–900 и 3000–9000 первая часть подчиняется правилу 3–10.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ثَلَاثُمِائَةِ كِتَابٍ؛ خَمْسَةُ آلَافِ طَالِبٍ.</b> — Триста книг; пять тысяч студентов.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">ثَلَاثُمِائَةِ كِتَابٍ؛ خَمْسَةُ آلَافِ طَالِبٍ.</b> найдите конструкцию «الْمِئَاتُ وَالْآلَافُ», определите её роль и только затем сопоставьте с переводом: «Триста книг; пять тысяч студентов.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '5', 'rule', 'После сотен и тысяч считаемое единственное родительное. В 300–900 и 3000–9000 первая часть подчиняется правилу 3–10.'),
('Мединский курс (Том 2)', '25', 'كَانَ وَمَا زَالَ («был» и «все еще»)', '<b>Суть правила.</b> Оба ناقصных глагола оставляют имя именительным и ставят сказуемое в винительный. كَانَ переносит состояние в прошлое, مَا زَالَ показывает продолжение.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَانَ الْبَابُ مَفْتُوحًا؛ مَا زَالَ الطَّالِبُ مَرِيضًا.</b> — Дверь была открыта; студент все еще болен.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كَانَ الْبَابُ مَفْتُوحًا؛ مَا زَالَ الطَّالِبُ مَرِيضًا.</b> найдите конструкцию «كَانَ وَمَا زَالَ», определите её роль и только затем сопоставьте с переводом: «Дверь была открыта; студент все еще болен.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '1', 'rule', 'Оба ناقصных глагола оставляют имя именительным и ставят сказуемое в винительный. كَانَ переносит состояние в прошлое, مَا زَالَ показывает продолжение.'),
('Мединский курс (Том 2)', '25', 'الْأَسْمَاءُ الْخَمْسَةُ (пять особых имен)', '<b>Суть правила.</b> أَبٌ، أَخٌ، حَمٌ، فُو، ذُو при выполнении условий склоняются буквами: و в именительном, ا в винительном, ي в родительном.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ أَبُوكَ؛ رَأَيْتُ أَبَاكَ؛ سَلَّمْتُ عَلَى أَبِيكَ.</b> — Твой отец пришел; я увидел и поприветствовал твоего отца.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جَاءَ أَبُوكَ؛ رَأَيْتُ أَبَاكَ؛ سَلَّمْتُ عَلَى أَبِيكَ.</b> найдите конструкцию «الْأَسْمَاءُ الْخَمْسَةُ», определите её роль и только затем сопоставьте с переводом: «Твой отец пришел; я увидел и поприветствовал твоего отца.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'أَبٌ، أَخٌ، حَمٌ، فُو، ذُو при выполнении условий склоняются буквами: و в именительном, ا в винительном, ي в родительном.'),
('Мединский курс (Том 2)', '25', 'شُرُوطُ الْأَسْمَاءِ الْخَمْسَةِ (условия склонения пяти имен)', '<b>Суть правила.</b> Форма должна быть единственной, не уменьшительной и находиться в идафе не к ي говорящего. Иначе используются обычные огласовки.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذَا أَخُو مُحَمَّدٍ.</b> — Это брат Мухаммада.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هَذَا أَخُو مُحَمَّدٍ.</b> найдите конструкцию «شُرُوطُ الْأَسْمَاءِ الْخَمْسَةِ», определите её роль и только затем сопоставьте с переводом: «Это брат Мухаммада.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '3', 'rule', 'Форма должна быть единственной, не уменьшительной и находиться в идафе не к ي говорящего. Иначе используются обычные огласовки.'),
('Мединский курс (Том 2)', '26', 'الْفِعْلُ الْمِثَالُ الْوَاوِيُّ (слабый глагол с و в начале)', '<b>Суть правила.</b> В المضارع ряда глаголов начальная و выпадает: وَعَدَ يَعِدُ، وَصَلَ يَصِلُ. В прошедшем она сохраняется; в повелительном не возвращается.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">وَصَلَ الْقِطَارُ؛ يَصِلُ غَدًا؛ عِدْ.</b> — Поезд прибыл; прибудет завтра; обещай.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">وَصَلَ الْقِطَارُ؛ يَصِلُ غَدًا؛ عِدْ.</b> найдите конструкцию «الْفِعْلُ الْمِثَالُ الْوَاوِيُّ», определите её роль и только затем сопоставьте с переводом: «Поезд прибыл; прибудет завтра; обещай.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'В المضارع ряда глаголов начальная و выпадает: وَعَدَ يَعِدُ، وَصَلَ يَصِلُ. В прошедшем она сохраняется; в повелительном не возвращается.'),
('Мединский курс (Том 2)', '26', 'التَّصْغِيرُ (уменьшительная форма)', '<b>Суть правила.</b> Трехбуквенное имя часто получает модель فُعَيْلٌ, передающую малый размер или ласковое отношение.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كِتَابٌ → كُتَيِّبٌ.</b> — Книга → книжечка.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">كِتَابٌ → كُتَيِّبٌ.</b> найдите конструкцию «التَّصْغِيرُ», определите её роль и только затем сопоставьте с переводом: «Книга → книжечка.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '2', 'rule', 'Трехбуквенное имя часто получает модель فُعَيْلٌ, передающую малый размер или ласковое отношение.'),
('Мединский курс (Том 2)', '26', 'اسْمُ التَّفْضِيلِ مِنَ الْمُضَعَّفِ (сравнительная степень удвоенного глагола)', '<b>Суть правила.</b> При построении أَفْعَلُ две одинаковые коренные буквы сохраняют удвоение.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">شَدَّ → أَشَدُّ.</b> — Быть сильным → сильнее.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">شَدَّ → أَشَدُّ.</b> найдите конструкцию «اسْمُ التَّفْضِيلِ مِنَ الْمُضَعَّفِ», определите её роль и только затем сопоставьте с переводом: «Быть сильным → сильнее.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '3', 'rule', 'При построении أَفْعَلُ две одинаковые коренные буквы сохраняют удвоение.'),
('Мединский курс (Том 2)', '26', 'هَا هُوَ ذَا (оборот «вот он»)', '<b>Суть правила.</b> هَا привлекает внимание, затем идет местоимение и указательное слово, согласованные с лицом и родом.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَا هُوَ ذَا؛ هَا هِيَ ذِهِ.</b> — Вот он; вот она.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هَا هُوَ ذَا؛ هَا هِيَ ذِهِ.</b> найдите конструкцию «هَا هُوَ ذَا», определите её роль и только затем сопоставьте с переводом: «Вот он; вот она.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '4', 'rule', 'هَا привлекает внимание, затем идет местоимение и указательное слово, согласованные с лицом и родом.'),
('Мединский курс (Том 2)', '26', 'يَجِبُ وَمَصْدَرُ ذَهَبَ («необходимо» и масдар ذَهَبَ)', '<b>Суть правила.</b> После يَجِبُ часто употребляется أَنْ + المضارع. Масдар ذَهَبَ — ذَهَابٌ и запоминается словарно.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَجِبُ أَنْ تَذْهَبَ؛ أُرِيدُ الذَّهَابَ.</b> — Тебе нужно пойти; я хочу пойти.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">يَجِبُ أَنْ تَذْهَبَ؛ أُرِيدُ الذَّهَابَ.</b> найдите конструкцию «يَجِبُ وَمَصْدَرُ ذَهَبَ», определите её роль и только затем сопоставьте с переводом: «Тебе нужно пойти; я хочу пойти.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '5', 'rule', 'После يَجِبُ часто употребляется أَنْ + المضارع. Масдар ذَهَبَ — ذَهَابٌ и запоминается словарно.'),
('Мединский курс (Том 2)', '27', 'الْفِعْلُ الْأَجْوَفُ (пустой глагол со слабой средней буквой)', '<b>Суть правила.</b> У глагола типа قَالَ/بَاعَ средняя و или ي превращается в долгую ا в одних формах и сокращается в других.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَالَ يَقُولُ؛ بَاعَ يَبِيعُ.</b> — Сказать; продавать.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">قَالَ يَقُولُ؛ بَاعَ يَبِيعُ.</b> найдите конструкцию «الْفِعْلُ الْأَجْوَفُ», определите её роль и только затем сопоставьте с переводом: «Сказать; продавать.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'У глагола типа قَالَ/بَاعَ средняя و или ي превращается в долгую ا в одних формах и сокращается в других.'),
('Мединский курс (Том 2)', '27', 'إِسْنَادُ الْأَجْوَفِ فِي الْمَاضِي (прошедшее пустого глагола)', '<b>Суть правила.</b> Перед подвижным окончанием долгий гласный сокращается: قَالَ, но قُلْتُ; بَاعَ, но بِعْتُ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَالُوا وَقُلْنَا.</b> — Они сказали, и мы сказали.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">قَالُوا وَقُلْنَا.</b> найдите конструкцию «إِسْنَادُ الْأَجْوَفِ فِي الْمَاضِي», определите её роль и только затем сопоставьте с переводом: «Они сказали, и мы сказали.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '2', 'rule', 'Перед подвижным окончанием долгий гласный сокращается: قَالَ, но قُلْتُ; بَاعَ, но بِعْتُ.'),
('Мединский курс (Том 2)', '27', 'الْأَجْوَفُ فِي الْمُضَارِعِ وَالْأَمْرِ (пустой глагол в المضارع и повелительном)', '<b>Суть правила.</b> В именительном/винительном долгий гласный сохраняется, а в усеченном перед сукуном выпадает. Повелительное берется от усеченной формы.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَقُولُ، لَنْ يَقُولَ، لَمْ يَقُلْ، قُلْ.</b> — Говорит; не будет говорить; не говорил; скажи.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">يَقُولُ، لَنْ يَقُولَ، لَمْ يَقُلْ، قُلْ.</b> найдите конструкцию «الْأَجْوَفُ فِي الْمُضَارِعِ وَالْأَمْرِ», определите её роль и только затем сопоставьте с переводом: «Говорит; не будет говорить; не говорил; скажи.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '3', 'rule', 'В именительном/винительном долгий гласный сохраняется, а в усеченном перед сукуном выпадает. Повелительное берется от усеченной формы.'),
('Мединский курс (Том 2)', '27', 'أَصْلُ الْحَرْفِ الْمُعْتَلِّ (как определить و или ي в корне)', '<b>Суть правила.</b> Смотрите на المضارع или масдар: قَالَ يَقُولُ указывает на و, بَاعَ يَبِيعُ — на ي.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">صَامَ يَصُومُ: الجذر ص و م.</b> — Поститься: корень ص و م.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">صَامَ يَصُومُ: الجذر ص و م.</b> найдите конструкцию «أَصْلُ الْحَرْفِ الْمُعْتَلِّ», определите её роль и только затем сопоставьте с переводом: «Поститься: корень ص و م.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '4', 'rule', 'Смотрите на المضارع или масдар: قَالَ يَقُولُ указывает на و, بَاعَ يَبِيعُ — на ي.'),
('Мединский курс (Том 2)', '27', 'الْقَسَمُ وَلَقَدْ وَظَنَّ (клятва, усиление и два дополнения)', '<b>Суть правила.</b> После وَاللهِ утверждение часто усиливается لَـ/قَدْ. ظَنَّ ставит два дополнения в винительный: кого считаем и кем.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">وَاللهِ لَقَدْ صَدَقَ؛ ظَنَنْتُ خَالِدًا طَبِيبًا.</b> — Клянусь Аллахом, он сказал правду; я считал Халида врачом.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">وَاللهِ لَقَدْ صَدَقَ؛ ظَنَنْتُ خَالِدًا طَبِيبًا.</b> найдите конструкцию «الْقَسَمُ وَلَقَدْ وَظَنَّ», определите её роль и только затем сопоставьте с переводом: «Клянусь Аллахом, он сказал правду; я считал Халида врачом.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '5', 'rule', 'После وَاللهِ утверждение часто усиливается لَـ/قَدْ. ظَنَّ ставит два дополнения в винительный: кого считаем и кем.'),
('Мединский курс (Том 2)', '28', 'الْفِعْلُ النَّاقِصُ (слабый глагол с последней و/ي)', '<b>Суть правила.</b> Последняя слабая буква меняется по форме: دَعَا يَدْعُو، رَمَى يَرْمِي. Вид буквы определяется المضارع и масдаром.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَدَى يَهْدِي؛ دَعَا يَدْعُو.</b> — Вести прямым путем; звать.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هَدَى يَهْدِي؛ دَعَا يَدْعُو.</b> найдите конструкцию «الْفِعْلُ النَّاقِصُ», определите её роль и только затем сопоставьте с переводом: «Вести прямым путем; звать.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Последняя слабая буква меняется по форме: دَعَا يَدْعُو، رَمَى يَرْمِي. Вид буквы определяется المضارع и масдаром.'),
('Мединский курс (Том 2)', '28', 'إِسْنَادُ النَّاقِصِ فِي الْمَاضِي (прошедшее слабого конечного глагола)', '<b>Суть правила.</b> Перед некоторыми окончаниями слабая буква меняется или выпадает: دَعَوْتُ، رَمَيْتُ، دَعَوْا، رَمَوْا.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَمَيْتُ الْكُرَةَ.</b> — Я бросил мяч.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">رَمَيْتُ الْكُرَةَ.</b> найдите конструкцию «إِسْنَادُ النَّاقِصِ فِي الْمَاضِي», определите её роль и только затем сопоставьте с переводом: «Я бросил мяч.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '2', 'rule', 'Перед некоторыми окончаниями слабая буква меняется или выпадает: دَعَوْتُ، رَمَيْتُ، دَعَوْا، رَمَوْا.'),
('Мединский курс (Том 2)', '28', 'النَّاقِصُ فِي الْمُضَارِعِ وَالْأَمْرِ (конечнослабый глагол в المضارع и повелительном)', '<b>Суть правила.</b> В именительном слабая буква сохраняется, в усеченном и повелительном удаляется; в винительном появляется фатха перед ней.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَمْشِي، لَنْ يَمْشِيَ، لَمْ يَمْشِ، اِمْشِ.</b> — Идет; не пойдет; не шел; иди.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">يَمْشِي، لَنْ يَمْشِيَ، لَمْ يَمْشِ، اِمْشِ.</b> найдите конструкцию «النَّاقِصُ فِي الْمُضَارِعِ وَالْأَمْرِ», определите её роль и только затем сопоставьте с переводом: «Идет; не пойдет; не шел; иди.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '3', 'rule', 'В именительном слабая буква сохраняется, в усеченном и повелительном удаляется; в винительном появляется фатха перед ней.'),
('Мединский курс (Том 2)', '28', 'رَأَى وَأَرِنِي («увидел» и «покажи мне»)', '<b>Суть правила.</b> رَأَى имеет особые изменения хамзы. Повелительное четвертой породы أَرَى — أَرِ, а с объектом: أَرِنِي.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите конструкцию из заголовка правила.</li><li>Определите роль каждого слова в предложении.</li><li>Сопоставьте форму с переводом и перечитайте пример целиком.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَرِنِي كِتَابَكَ.</b> — Покажи мне свою книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">أَرِنِي كِتَابَكَ.</b> найдите конструкцию «رَأَى وَأَرِنِي», определите её роль и только затем сопоставьте с переводом: «Покажи мне свою книгу.».</div><div class="rule-note"><b>Частая ошибка.</b> Не разбирайте отдельное окончание вне контекста: сначала установите функцию всего слова и конструкции.</div>', '4', 'rule', 'رَأَى имеет особые изменения хамзы. Повелительное четвертой породы أَرَى — أَرِ, а с объектом: أَرِنِي.'),
('Мединский курс (Том 2)', '29', 'الْفِعْلُ الْمُضَعَّفُ (удвоенный глагол)', '<b>Суть правила.</b> Если вторая и третья коренные одинаковы, они сливаются под шаддой: رَدَّ، يَرُدُّ.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَدَّ الطَّالِبُ الْكِتَابَ.</b> — Студент вернул книгу.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">رَدَّ الطَّالِبُ الْكِتَابَ.</b> найдите конструкцию «الْفِعْلُ الْمُضَعَّفُ», определите её роль и только затем сопоставьте с переводом: «Студент вернул книгу.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '1', 'rule', 'Если вторая и третья коренные одинаковы, они сливаются под шаддой: رَدَّ، يَرُدُّ.'),
('Мединский курс (Том 2)', '29', 'إِسْنَادُ الْمُضَعَّفِ فِي الْمَاضِي (прошедшее удвоенного глагола)', '<b>Суть правила.</b> Перед окончанием с сукуном шадда раскрывается: رَدَدْتُ، رَدَدْنَا. Без такого окончания остается رَدَّ، رَدُّوا.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ظَنَنْتُ؛ ظَنُّوا.</b> — Я подумал; они подумали.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">ظَنَنْتُ؛ ظَنُّوا.</b> найдите конструкцию «إِسْنَادُ الْمُضَعَّفِ فِي الْمَاضِي», определите её роль и только затем сопоставьте с переводом: «Я подумал; они подумали.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '2', 'rule', 'Перед окончанием с сукуном шадда раскрывается: رَدَدْتُ، رَدَدْنَا. Без такого окончания остается رَدَّ، رَدُّوا.'),
('Мединский курс (Том 2)', '29', 'الْمُضَعَّفُ فِي الْمُضَارِعِ وَالْأَمْرِ (удвоенный глагол в المضارع и повелительном)', '<b>Суть правила.</b> В обычной форме шадда сохраняется. В усеченном возможна форма с раскрытием; повелительное обычно сохраняет удвоение.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَرُدُّ، لَنْ يَرُدَّ، لَمْ يَرُدَّ/يَرْدُدْ، رُدَّ.</b> — Возвращает; не будет; не вернул; верни.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">يَرُدُّ، لَنْ يَرُدَّ، لَمْ يَرُدَّ/يَرْدُدْ، رُدَّ.</b> найдите конструкцию «الْمُضَعَّفُ فِي الْمُضَارِعِ وَالْأَمْرِ», определите её роль и только затем сопоставьте с переводом: «Возвращает; не будет; не вернул; верни.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '3', 'rule', 'В обычной форме шадда сохраняется. В усеченном возможна форма с раскрытием; повелительное обычно сохраняет удвоение.'),
('Мединский курс (Том 2)', '29', 'قَطُّ وَأَبَدًا (наречия усиления отрицания)', '<b>Суть правила.</b> قَطُّ относится преимущественно к прошлому, أَبَدًا — к будущему; выбирайте по времени.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите: это сообщение, отрицание прошлого, будущего или запрет.</li><li>Выберите нужную частицу.</li><li>Проверьте наклонение и конечную огласовку глагола.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَمْ أَكْذِبْ قَطُّ؛ لَنْ أَكْذِبَ أَبَدًا.</b> — Я никогда не лгал; я никогда не буду лгать.</li><li><b dir="rtl" lang="ar">لَمْ يَحْضُرْ خَالِدٌ، وَلَنْ يَتَأَخَّرَ غَدًا.</b> — Халид не пришёл, а завтра не опоздает.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">لَمْ أَكْذِبْ قَطُّ؛ لَنْ أَكْذِبَ أَبَدًا.</b> найдите конструкцию «قَطُّ وَأَبَدًا», определите её роль и только затем сопоставьте с переводом: «Я никогда не лгал; я никогда не буду лгать.».</div><div class="rule-note"><b>Частая ошибка.</b> После لَمْ и запретительной لَا глагол ставится в джазм; после لَنْ — в насб.</div>', '4', 'rule', 'قَطُّ относится преимущественно к прошлому, أَبَدًا — к будущему; выбирайте по времени.'),
('Мединский курс (Том 2)', '29', 'مُرَاجَعَةُ الْأَفْعَالِ الْمُعْتَلَّةِ (сводка слабых глаголов)', '<b>Суть правила.</b> مثال имеет слабую первую, أجوف — среднюю, ناقص — последнюю коренную. Место слабой буквы определяет изменения.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">وَعَدَ مثال، قَالَ أجوف، دَعَا ناقص.</b> — Обещать — начально-слабый; говорить — пустой; звать — конечнослабый.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">وَعَدَ مثال، قَالَ أجوف، دَعَا ناقص.</b> найдите конструкцию «مُرَاجَعَةُ الْأَفْعَالِ الْمُعْتَلَّةِ», определите её роль и только затем сопоставьте с переводом: «Обещать — начально-слабый; говорить — пустой; звать — конечнослабый.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '5', 'rule', 'مثال имеет слабую первую, أجوف — среднюю, ناقص — последнюю коренную. Место слабой буквы определяет изменения.'),
('Мединский курс (Том 2)', '30', 'أَلِفُ الِاثْنَيْنِ فِي الْأَفْعَالِ (двойственное число глагола)', '<b>Суть правила.</b> Для «они двое» и «вы двое» используются формы ذَهَبَا، ذَهَبَتَا، يَذْهَبَانِ، تَذْهَبَانِ، اِذْهَبَا، لَا تَذْهَبَا.<div class="rule-steps"><b>Как применять.</b><ol><li>Определите разряд и форму числительного.</li><li>Проверьте род и падеж числительного.</li><li>Поставьте считаемое слово в требуемое число и падеж.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">الطَّالِبَانِ ذَهَبَا وَالطَّالِبَتَانِ ذَهَبَتَا.</b> — Два студента ушли, и две студентки ушли.</li><li><b dir="rtl" lang="ar">فِي الْفَصْلِ خَمْسَةَ عَشَرَ طَالِبًا.</b> — В классе пятнадцать учеников.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">الطَّالِبَانِ ذَهَبَا وَالطَّالِبَتَانِ ذَهَبَتَا.</b> найдите конструкцию «أَلِفُ الِاثْنَيْنِ فِي الْأَفْعَالِ», определите её роль и только затем сопоставьте с переводом: «Два студента ушли, и две студентки ушли.».</div><div class="rule-note"><b>Частая ошибка.</b> Не переносите одну схему согласования на все числа: правила 1–2, 3–10, 11–99, сотен и тысяч различаются.</div>', '1', 'rule', 'Для «они двое» и «вы двое» используются формы ذَهَبَا، ذَهَبَتَا، يَذْهَبَانِ، تَذْهَبَانِ، اِذْهَبَا، لَا تَذْهَبَا.'),
('Мединский курс (Том 2)', '30', 'الْمُثَنَّى مِنَ الْأَفْعَالِ الْخَمْسَةِ (двойственные формы среди пяти глаголов)', '<b>Суть правила.</b> يَفْعَلَانِ и تَفْعَلَانِ именительны с ن; после أَنْ، لَنْ، لَمْ и запрета ن удаляется.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите словарную форму и корень.</li><li>Определите время, лицо, число и род.</li><li>Добавьте показатель лица и окончание, затем проверьте конечную огласовку.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُمَا يَكْتُبَانِ؛ لَنْ يَكْتُبَا؛ لَمْ يَكْتُبَا.</b> — Они двое пишут; не будут писать; не писали.</li><li><b dir="rtl" lang="ar">كَتَبْنَا الدَّرْسَ، وَالآنَ نَقْرَؤُهُ.</b> — Мы написали урок, а теперь читаем его.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هُمَا يَكْتُبَانِ؛ لَنْ يَكْتُبَا؛ لَمْ يَكْتُبَا.</b> найдите конструкцию «الْمُثَنَّى مِنَ الْأَفْعَالِ الْخَمْسَةِ», определите её роль и только затем сопоставьте с переводом: «Они двое пишут; не будут писать; не писали.».</div><div class="rule-note"><b>Частая ошибка.</b> Не определяйте лицо только по переводу: сначала найдите приставку и окончание арабской формы.</div>', '2', 'rule', 'يَفْعَلَانِ и تَفْعَلَانِ именительны с ن; после أَنْ، لَنْ، لَمْ и запрета ن удаляется.'),
('Мединский курс (Том 2)', '31', 'النَّعْتُ وَالْمَنْعُوتُ (прилагательное и определяемое имя)', '<b>Суть правила.</b> Прилагательное следует после существительного и описывает его. Определяемое имя называется مَنْعُوت, определение — نَعْت.<div class="rule-steps"><b>Как применять.</b><ol><li>Поставьте вопросительное слово в начало.</li><li>Сохраните обычное управление глагола или предлога.</li><li>Проверьте, отвечает ли фраза именно на заданный вопрос.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ طَالِبٌ جَدِيدٌ.</b> — Пришел новый студент.</li><li><b dir="rtl" lang="ar">مَاذَا تَقْرَأُ؟ أَقْرَأُ كِتَابًا.</b> — Что ты читаешь? Я читаю книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">جَاءَ طَالِبٌ جَدِيدٌ.</b> найдите конструкцию «النَّعْتُ وَالْمَنْعُوتُ», определите её роль и только затем сопоставьте с переводом: «Пришел новый студент.».</div><div class="rule-note"><b>Частая ошибка.</b> Не смешивайте مَنْ для разумных лиц и مَا / مَاذَا для предметов, явлений и прочего неразумного.</div>', '1', 'rule', 'Прилагательное следует после существительного и описывает его. Определяемое имя называется مَنْعُوت, определение — نَعْت.'),
('Мединский курс (Том 2)', '31', 'مُطَابَقَةُ النَّعْتِ لِلْمَنْعُوتِ (согласование определения)', '<b>Суть правила.</b> Определение согласуется в четырех признаках: падеже, определенности, роде и числе.<div class="rule-steps"><b>Как применять.</b><ol><li>Поставьте вопросительное слово в начало.</li><li>Сохраните обычное управление глагола или предлога.</li><li>Проверьте, отвечает ли фраза именно на заданный вопрос.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَةَ الْجَدِيدَةَ.</b> — Я увидел новую студентку.</li><li><b dir="rtl" lang="ar">مَاذَا تَقْرَأُ؟ أَقْرَأُ كِتَابًا.</b> — Что ты читаешь? Я читаю книгу.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَةَ الْجَدِيدَةَ.</b> найдите конструкцию «مُطَابَقَةُ النَّعْتِ لِلْمَنْعُوتِ», определите её роль и только затем сопоставьте с переводом: «Я увидел новую студентку.».</div><div class="rule-note"><b>Частая ошибка.</b> Не смешивайте مَنْ для разумных лиц и مَا / مَاذَا для предметов, явлений и прочего неразумного.</div>', '2', 'rule', 'Определение согласуется в четырех признаках: падеже, определенности, роде и числе.'),
('Мединский курс (Том 2)', '31', 'نَعْتُ جَمْعِ غَيْرِ الْعَاقِلِ (определение неодушевленного множественного)', '<b>Суть правила.</b> Неодушевленное множественное обычно получает определение женского единственного рода.<div class="rule-steps"><b>Как применять.</b><ol><li>Найдите определяемое существительное.</li><li>Согласуйте прилагательное в роде, числе и определённости.</li><li>Проверьте падежные окончания обоих слов.</li></ol></div><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذِهِ كُتُبٌ جَدِيدَةٌ.</b> — Это новые книги.</li><li><b dir="rtl" lang="ar">هَذِهِ سَيَّارَةٌ جَدِيدَةٌ، وَذَلِكَ بَيْتٌ كَبِيرٌ.</b> — Это новая машина, а то большой дом.</li></ul><div class="rule-example-analysis"><b>Разбор первого примера.</b> В выражении <b dir="rtl" lang="ar">هَذِهِ كُتُبٌ جَدِيدَةٌ.</b> найдите конструкцию «نَعْتُ جَمْعِ غَيْرِ الْعَاقِلِ», определите её роль и только затем сопоставьте с переводом: «Это новые книги.».</div><div class="rule-note"><b>Частая ошибка.</b> Прилагательное не получает артикль само по себе, если определяемое существительное остаётся неопределённым.</div>', '3', 'rule', 'Неодушевленное множественное обычно получает определение женского единственного рода.');
